0001	{"-- 0001_extensions_and_enums.sql\n-- Supabase/PostgreSQL foundation for the showroom CMS database.\n-- Scope: required extensions and domain enums only.\n\nbegin","create schema if not exists extensions","create extension if not exists pgcrypto with schema extensions","create extension if not exists unaccent with schema extensions","create extension if not exists pg_trgm with schema extensions","grant usage on schema public to anon, authenticated, service_role","grant usage on schema extensions to anon, authenticated, service_role","do $$\nbegin\n  create type public.locale_code as enum ('vi', 'en');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.cms_role as enum ('admin', 'editor');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.publish_status as enum ('draft', 'published', 'archived');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.media_resource_type as enum ('image', 'video');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.media_status as enum ('active', 'archived');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.storage_provider as enum ('supabase_storage', 'cloudinary');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.product_group_key as enum (\n    'wooden_furniture',\n    'sanitary_equipment',\n    'tiles',\n    'project_solutions'\n  );\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.quote_status as enum ('new', 'contacted', 'qualified', 'closed', 'spam');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.notification_status as enum ('pending', 'sent', 'failed', 'skipped');\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.social_platform as enum (\n    'facebook',\n    'zalo',\n    'youtube',\n    'tiktok',\n    'instagram',\n    'other'\n  );\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.ai_target_type as enum (\n    'product',\n    'blog_post',\n    'content_page',\n    'seo',\n    'translation'\n  );\nexception\n  when duplicate_object then null;\nend\n$$","do $$\nbegin\n  create type public.ai_draft_status as enum ('draft', 'accepted', 'discarded');\nexception\n  when duplicate_object then null;\nend\n$$","comment on type public.locale_code is 'Supported public content locales.'","comment on type public.cms_role is 'CMS roles. Role Model Option A: editor manages publishable content only; admin manages privileged data.'","comment on type public.publish_status is 'Publish lifecycle for public content.'","comment on type public.media_resource_type is 'Media types allowed by the launch design.'","comment on type public.media_status is 'Reusable media lifecycle status.'","comment on type public.storage_provider is 'Media metadata provider. Supports Supabase Storage and Cloudinary.'","comment on type public.product_group_key is 'Top-level public product group identifiers.'","comment on type public.quote_status is 'Private quote lead workflow status.'","comment on type public.notification_status is 'Quote notification delivery status.'","comment on type public.social_platform is 'Configured public social link platform.'","comment on type public.ai_target_type is 'AI draft target category. target_id is polymorphic and cannot be enforced by a single FK.'","comment on type public.ai_draft_status is 'Human review status for draft-only AI output.'",commit}	extensions_and_enums
0002	{"-- 0002_helpers_and_triggers.sql\n-- Generic helper functions and trigger functions.\n-- Table-specific trigger attachments are added after table creation.\n\nbegin","create or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$","comment on function public.set_updated_at() is\n  'BEFORE UPDATE trigger function that keeps updated_at current.'","create or replace function public.set_publish_timestamps()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if new.status = 'published'::public.publish_status\n     and (tg_op = 'INSERT' or old.status is distinct from 'published'::public.publish_status)\n  then\n    new.published_at = coalesce(new.published_at, now());\n  end if;\n\n  return new;\nend;\n$$","comment on function public.set_publish_timestamps() is\n  'Sets published_at when a publishable row first transitions to published.'","create or replace function public.set_product_archive_timestamp()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if new.status = 'archived'::public.publish_status\n     and (tg_op = 'INSERT' or old.status is distinct from 'archived'::public.publish_status)\n  then\n    new.archived_at = coalesce(new.archived_at, now());\n  end if;\n\n  return new;\nend;\n$$","comment on function public.set_product_archive_timestamp() is\n  'Sets products.archived_at when a product first transitions to archived.'","-- PostgreSQL marks unaccent as stable because dictionaries may change.\n-- For application search indexes, this immutable wrapper is a common pragmatic\n-- Supabase pattern. Reindex if the unaccent dictionary is changed.\ncreate or replace function public.immutable_unaccent(input text)\nreturns text\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select extensions.unaccent(coalesce(input, ''));\n$$","comment on function public.immutable_unaccent(text) is\n  'Immutable wrapper for unaccent, used by trigram/search indexes. Reindex if dictionary config changes.'","create or replace function public.to_simple_tsvector(variadic parts text[])\nreturns tsvector\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select to_tsvector(\n    'simple',\n    public.immutable_unaccent(lower(coalesce(array_to_string(parts, ' '), '')))\n  );\n$$","comment on function public.to_simple_tsvector(text[]) is\n  'Builds an accent-insensitive simple-language tsvector from text fragments.'","create or replace function public.set_product_translation_search_text()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.search_text = public.to_simple_tsvector(\n    new.name,\n    new.summary,\n    new.material,\n    new.price_display_text,\n    new.dimension_display_text\n  );\n  return new;\nend;\n$$","comment on function public.set_product_translation_search_text() is\n  'Maintains product_translations.search_text for localized product search.'","create or replace function public.set_blog_post_translation_search_text()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.search_text = public.to_simple_tsvector(\n    new.title,\n    new.excerpt,\n    new.seo_title,\n    new.seo_description\n  );\n  return new;\nend;\n$$","comment on function public.set_blog_post_translation_search_text() is\n  'Maintains blog_post_translations.search_text for localized blog search.'","create or replace function public.compact_text(input text)\nreturns text\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select nullif(regexp_replace(btrim(coalesce(input, '')), '\\\\s+', ' ', 'g'), '');\n$$","comment on function public.compact_text(text) is\n  'Trims text, collapses repeated whitespace, and returns null for blank values.'","create or replace function public.prevent_update_delete()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  raise exception '% rows are append-only', tg_table_name\n    using errcode = '42501';\nend;\n$$","comment on function public.prevent_update_delete() is\n  'Blocks UPDATE/DELETE on append-only operational tables when attached as a trigger.'",commit}	helpers_and_triggers
0003	{"-- 0003_core_tables.sql\n-- Core table definitions. Foreign keys, unique indexes, checks, RLS and RPCs\n-- are intentionally split into later migrations for reviewability.\n\nbegin","create table if not exists public.profiles (\n  id uuid primary key,\n  email text not null,\n  full_name text not null,\n  role public.cms_role not null default 'editor',\n  is_active boolean not null default true,\n  last_login_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","comment on table public.profiles is\n  'Admin/Editor CMS profile. id references auth.users(id). profiles.email is duplicated for admin display/search; auth.users.email remains the identity source of truth.'","create table if not exists public.media_assets (\n  id uuid primary key default extensions.gen_random_uuid(),\n  storage_provider public.storage_provider not null default 'supabase_storage',\n  bucket text,\n  object_path text,\n  cloudinary_public_id text,\n  public_url text not null,\n  resource_type public.media_resource_type not null,\n  mime_type text not null,\n  format text not null,\n  size_bytes bigint not null,\n  width int,\n  height int,\n  duration_seconds numeric(10,2),\n  owner_context text,\n  status public.media_status not null default 'active',\n  uploaded_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","comment on table public.media_assets is\n  'Reusable media metadata for Supabase Storage or Cloudinary. Upload validation for type, size, dimensions, and ownership context remains server-side.'","create table if not exists public.media_asset_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  media_id uuid not null,\n  locale public.locale_code not null,\n  alt_text text,\n  caption text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.site_settings (\n  id uuid primary key default extensions.gen_random_uuid(),\n  singleton_key text not null default 'default',\n  logo_media_id uuid,\n  favicon_media_id uuid,\n  default_og_image_media_id uuid,\n  contact_phone text,\n  contact_email text,\n  quote_sender_email text,\n  updated_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on table public.site_settings is\n  'Singleton site settings row. Privileged settings and integration secrets must remain admin/service-only and should not be stored in public client code.'","create table if not exists public.site_setting_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  site_settings_id uuid not null,\n  locale public.locale_code not null,\n  brand_name text not null,\n  contact_address text,\n  seo_default_title text not null,\n  seo_default_description text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.social_links (\n  id uuid primary key default extensions.gen_random_uuid(),\n  site_settings_id uuid not null,\n  platform public.social_platform not null,\n  label text,\n  url text not null,\n  is_enabled boolean not null default true,\n  share_enabled boolean not null default false,\n  sort_order int not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.quote_recipients (\n  id uuid primary key default extensions.gen_random_uuid(),\n  site_settings_id uuid not null,\n  email text not null,\n  label text,\n  is_active boolean not null default true,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on table public.quote_recipients is\n  'Private notification recipients for quote leads. Admin/service only.'","create table if not exists public.content_pages (\n  id uuid primary key default extensions.gen_random_uuid(),\n  key text not null,\n  status public.publish_status not null default 'draft',\n  published_at timestamptz,\n  created_by uuid,\n  updated_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.content_page_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  page_id uuid not null,\n  locale public.locale_code not null,\n  slug text not null,\n  title text not null,\n  lead text,\n  body_json jsonb,\n  seo_title text,\n  seo_description text,\n  og_image_media_id uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.page_sections (\n  id uuid primary key default extensions.gen_random_uuid(),\n  page_id uuid not null,\n  section_key text not null,\n  section_type text not null,\n  sort_order int not null default 0,\n  is_enabled boolean not null default true,\n  media_id uuid,\n  settings_json jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on column public.page_sections.media_id is\n  'Single section hero/inline media reference. page_media stores reusable page galleries or multiple contextual assets.'","create table if not exists public.page_section_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  section_id uuid not null,\n  locale public.locale_code not null,\n  title text,\n  subtitle text,\n  body_json jsonb,\n  cta_label text,\n  cta_href text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.page_media (\n  id uuid primary key default extensions.gen_random_uuid(),\n  page_id uuid not null,\n  media_