 created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.product_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  product_id uuid not null,\n  locale public.locale_code not null,\n  slug text not null,\n  name text not null,\n  summary text not null,\n  description_json jsonb not null,\n  material text,\n  price_display_text text,\n  dimension_display_text text,\n  seo_title text,\n  seo_description text,\n  og_image_media_id uuid,\n  search_text tsvector,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.product_media (\n  id uuid primary key default extensions.gen_random_uuid(),\n  product_id uuid not null,\n  media_id uuid not null,\n  context text not null default 'gallery',\n  is_primary boolean not null default false,\n  sort_order int not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.product_attribute_definitions (\n  id uuid primary key default extensions.gen_random_uuid(),\n  key text not null,\n  data_type text not null default 'text',\n  filterable boolean not null default true,\n  status public.publish_status not null default 'published',\n  sort_order int not null default 0,\n  created_by uuid,\n  updated_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.product_attribute_definition_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  definition_id uuid not null,\n  locale public.locale_code not null,\n  label text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.product_attribute_options (\n  id uuid primary key default extensions.gen_random_uuid(),\n  definition_id uuid not null,\n  key text not null,\n  swatch_hex text,\n  status public.publish_status not null default 'published',\n  sort_order int not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.product_attribute_option_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  option_id uuid not null,\n  locale public.locale_code not null,\n  label text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.product_attribute_values (\n  id uuid primary key default extensions.gen_random_uuid(),\n  product_id uuid not null,\n  attribute_definition_id uuid not null,\n  attribute_option_id uuid,\n  value_text_vi text,\n  value_text_en text,\n  value_number numeric(12,2),\n  value_boolean boolean,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on table public.product_attribute_values is\n  'Product attribute value table supports either option-based values or one scalar value shape. SQL checks in 0005 reject mixed states where possible.'","create table if not exists public.blog_categories (\n  id uuid primary key default extensions.gen_random_uuid(),\n  status public.publish_status not null default 'draft',\n  sort_order int not null default 0,\n  created_by uuid,\n  updated_by uuid,\n  published_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.blog_category_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  category_id uuid not null,\n  locale public.locale_code not null,\n  slug text not null,\n  name text not null,\n  description text,\n  seo_title text,\n  seo_description text,\n  og_image_media_id uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.blog_posts (\n  id uuid primary key default extensions.gen_random_uuid(),\n  category_id uuid not null,\n  author_id uuid not null,\n  cover_media_id uuid,\n  status public.publish_status not null default 'draft',\n  featured boolean not null default false,\n  published_at timestamptz,\n  created_by uuid,\n  updated_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.blog_post_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  post_id uuid not null,\n  locale public.locale_code not null,\n  slug text not null,\n  title text not null,\n  excerpt text not null,\n  body_json jsonb not null,\n  seo_title text,\n  seo_description text,\n  og_image_media_id uuid,\n  search_text tsvector,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.showrooms (\n  id uuid primary key default extensions.gen_random_uuid(),\n  code text,\n  hotline text not null,\n  google_maps_embed_url text not null,\n  google_maps_fallback_url text not null,\n  latitude numeric(10,7),\n  longitude numeric(10,7),\n  status public.publish_status not null default 'draft',\n  sort_order int not null default 0,\n  created_by uuid,\n  updated_by uuid,\n  published_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create table if not exists public.showroom_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  showroom_id uuid not null,\n  locale public.locale_code not null,\n  name text not null,\n  address text not null,\n  opening_hours text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.showroom_media (\n  id uuid primary key default extensions.gen_random_uuid(),\n  showroom_id uuid not null,\n  media_id uuid not null,\n  is_primary boolean not null default false,\n  sort_order int not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.quote_requests (\n  id uuid primary key default extensions.gen_random_uuid(),\n  full_name text not null,\n  phone text not null,\n  email text,\n  company text,\n  service text,\n  message text not null,\n  preferred_locale public.locale_code not null,\n  product_id uuid,\n  category_id uuid,\n  source_path text not null,\n  source_url text,\n  ip_hash text,\n  user_agent text,\n  status public.quote_status not null default 'new',\n  assigned_to uuid,\n  admin_notes text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","comment on table public.quote_requests is\n  'Private lead data. Public visitors must use submit_quote_request(payload jsonb) or a service-role Edge Function, and must not select this table.'","create table if not exists public.quote_request_events (\n  id uuid primary key default extensions.gen_random_uuid(),\n  quote_request_id uuid not null,\n  actor_id uuid,\n  old_status public.quote_status,\n  new_status public.quote_status,\n  note text,\n  created_at timestamptz not null default now()\n)","comment on table public.quote_request_events is\n  'Append-only quote lead workflow history.'","create table if not exists public.quote_notifications (\n  id uuid primary key default extensions.gen_random_uuid(),\n  quote_request_id uuid not null,\n  recipient_email text not null,\n  provider text not null default 'resend',\n  provider_message_id text,\n  status public.notification_status not null default 'pending',\n  attempt_count int not null default 0,\n  last_error text,\n  sent_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create table if not exists public.ai_drafts (\n  id uuid primary key default extensions.gen_random_uuid(),\n  target_type public.ai_target_type not null,\n  target_id uuid,\n  locale public.locale_code,\n  prompt_type text not null,\n  prompt_input_hash text,\n  output_json jsonb not null,\n  status public.ai_draft_status not null default 'draft',\n  requested_by uuid not null,\n  reviewed_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on table public.ai_drafts is\n  'Draft-only AI output. target_id is polymorphic by target_type, so PostgreSQL cannot enforce a single FK. Enforce target-specific permissions in server code/RLS-aware RPCs.'","create table if not exists public.audit_logs (\n  id uuid primary key default extensions.gen_random_uuid(),\n  actor_id uuid,\n  action text not null,\n  entity_type text not null,\n  entity_id uuid,\n  metadata jsonb,\n  created_at timestamptz not null default now()\n)","comment on table public.audit_logs is\n  'Trusted mutation audit trail. Prefer service-role writes from server code; admin reads only.'",commit}	core_tables
0004	{"-- 0004_foreign_keys_indexes_triggers.sql\n-- Foreign keys, non-unique indexes, and table trigger attachments.\n\nbegin","-- Auth/RBAC\nalter table public.profiles\n  add constraint fk_profiles_auth_users\n  foreign key (id) references auth.users(id)\n  on delete cascade","-- Media\nalter table public.media_assets\n  add constraint fk_media_assets_uploaded_by\n  foreign key (uploaded_by) references public.profiles(id)\n  on delete set null","alter table public.media_asset_translations\n  add constraint fk_media_asset_translations_media\n  foreign key (media_id) references public.media_assets(id)\n  on delete cascade","-- Site settings\nalter table public.site_settings\n  add constraint fk_site_settings_logo_media\n  foreign key (logo_media_id) references public.media_assets(id)\n  on delete set null,\n  add constraint fk_site_settings_favicon_media\n  foreign key (favicon_media_id) references public.media_assets(id)\n  on delete set null,\n  add constraint fk_site_settings_default_og_media\n  foreign key (default_og_image_media_id) references public.media_assets(id)\n  on delete set null,\n  add constraint fk_site_settings_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.site_setting_translations\n  add constraint fk_site_setting_translations_settings\n  foreign key (site_settings_id) references public.site_settings(id)\n  on delete cascade","alter table public.social_links\n  add constraint fk_social_links_settings\n  foreign key (site_settings_id) references public.site_settings(id)\n  on delete cascade","alter table public.quote_recipients\n  add constraint fk_quote_recipients_settings\n  foreign key (site_settings_id) references public.site_settings(id)\n  on delete cascade,\n  add constraint fk_quote_recipients_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null","-- CMS pages\nalter table public.content_pages\n  add constraint fk_content_pages_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_content_pages_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.content_page_translations\n  add constraint fk_content_page_translations_page\n  foreign key (page_id) references public.content_pages(id)\n  on delete cascade,\n  add constraint fk_content_page_translations_og_media\n  foreign key (og_image_media_id) references public.media_assets(id)\n  on delete set null","alter table public.page_sections\n  add constraint fk_page_sections_page\n  foreign key (page_id) references public.content_pages(id)\n  on delete cascade,\n  add constraint fk_page_sections_media\n  foreign key (media_id) references public.media_assets(id)\n  on delete set null","alter table public.page_section_translations\n  add constraint fk_page_section_translations_section\n  foreign key (section_id) references public.page_sections(id)\n  on delete cascade","alter table public.page_media\n  add constraint fk_page_media_page\n  foreign key (page_id) references public.content_pages(id)\n  on delete cascade,\n  add constraint fk_page_media_media\n  foreign key (media_id) references public.media_assets(id)\n  on delete cascade","-- Product catalog\nalter table public.product_categories\n  add constraint fk_product_categories_parent\n  foreign key (parent_id) references public.product_categories(id)\n  on delete set null,\n  add constraint fk_product_categories_image_media\n  foreign key (image_media_id) references public.media_assets(id)\n  on delete set null,\n  add constraint fk_product_categories_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_product_categories_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.product_category_translations\n  add constraint fk_product_category_translations_category\n  foreign key (category_id) references public.product_categories(id)\n  on delete cascade,\n  add constraint fk_product_category_translations_og_media\n  foreign key (og_image_media_id) references public.media_assets(id)\n  on delete set null","alter table public.products\n  add constraint fk_products_category\n  foreign key (category_id) references public.product_categories(id)\n  on delete restrict,\n  add constraint fk_products_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_products_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.product_translations\n  add constraint fk_product_translations_product\n  foreign key (product_id) references public.products(id)\n  on delete cascade,\n  add constraint fk_product_translations_og_media\n  foreign key (og_image_media_id) references public.media_assets(id)\n  on delete set null","alter table public.product_media\n  add constraint fk_product_media_product\n  foreign key (product_id) references public.products(id)\n  on delete cascade,\n  add constraint fk_product_media_media\n  foreign key (media_id) references public.media_assets(id)\n  on delete cascade","alter table public.product_attribute_definitions\n  add constraint fk_product_attribute_definitions_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_product_attribute_definitions_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.product_attribute_definition_translations\n  add constraint fk_product_attribute_definition_translations_definition\n  foreign key (definition_id) references public.product_attribute_definitions(id)\n  on delete cascade","alter table public.product_attribute_options\n  add constraint fk_product_attribute_options_definition\n  foreign key (definition_id) references public.product_attribute_definitions(id)\n  on delete cascade,\n  add constraint uq_product_attribute_options_id_definition\n  unique (id, definition_id)","alter table public.product_attribute_option_translations\n  add constraint fk_product_attribute_option_translations_option\n  foreign key (option_id) references public.product_attribute_options(id)\n  on delete cascade","alter table public.product_attribute_values\n  add constraint fk_product_attribute_values_product\n  foreign key (product_id) references public.products(id)\n  on delete cascade,\n  add constraint fk_product_attribute_values_definition\n  foreign key (attribute_definition_id) references public.product_attribute_definitions(id)\n  on delete restrict,\n  add constraint fk_product_attribute_values_option\n  foreign key (attribute_option_id) references public.product_attribute_options(id)\n  on delete restrict,\n  add constraint fk_product_attribute_values_option_matches_definition\n  foreign key (attribute_option_id, attribute_definition_id)\n  references public.product_attribute_options(id, definition_id)\n  on delete restrict","-- Blog\nalter table public.blog_categories\n  add constraint fk_blog_categories_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_blog_categories_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.blog_category_translations\n  add constraint fk_blog_category_translations_category\n  foreign key (category_id) references public.blog_categories(id)\n  on delete cascade,\n  add constraint fk_blog_category_translations_og_media\n  foreign key (og_image_media_id) references public.media_assets(id)\n  on delete set null","alter table public.blog_posts\n  add constraint fk_blog_posts_category\n  foreign key (category_id) references public.blog_categories(id)\n  on delete restrict,\n  add constraint fk_blog_posts_author\n  foreign key (author_id) references public.profiles(id)\n  on delete restrict,\n  add constraint fk_blog_posts_cover_media\n  foreign key (cover_media_id) references public.media_assets(id)\n  on delete set null,\n  add constraint fk_blog_posts_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_blog_posts_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.blog_post_translations\n  add constraint fk_blog_post_translations_post\n  foreign key (post_id) references public.blog_posts(id)\n  on delete cascade,\n  add constraint fk_blog_post_translations_og_media\n  foreign key (og_image_media_id) references public.media_assets(id)\n  on delete set null","-- Showrooms\nalter table public.showrooms\n  add constraint fk_showrooms_created_by\n  foreign key (created_by) references public.profiles(id)\n  on delete set null,\n  add constraint fk_showrooms_updated_by\n  foreign key (updated_by) references public.profiles(id)\n  on delete set null","alter table public.showroom_translations\n  add constraint fk_showroom_translations_showroom\n  foreign key (showroom_id) references public.showrooms(id)\n  on delete cascade","alter table public.showroom_media\n  add constraint fk_showroom_media_showroom\n  foreign key (showroom_id) references public.showrooms(id)\n  on delete cascade,\n  add constraint fk_showroom_media_media\n  foreign key (media_id) references public.media_assets(id)\n  on delete cascade","-- Quote leads\nalter table public.quote_requests\n  add constraint fk_quote_requests_product\n  foreign key (product_id) references public.products(id)\n  on delete set null,\n  add constraint fk_quote_requests_category\n  foreign key (category_id) references public.product_categories(id)\n  on delete set null,\n  add constraint fk_quote_requests_assigned_to\n  foreign key (assigned_to) references public.profiles(id)\n  on delete set null","alter table public.quote_request_events\n  add constraint fk_quote_request_events_quote_request\n  foreign key (quote_request_id) references public.quote_requests(id)\n  on delete cascade,\n  add constraint fk_quote_request_events_actor\n  foreign key (actor_id) references public.profiles(id)\n  on delete set null","alter table public.quote_notifications\n  add constraint fk_quote_notifications_quote_request\n  foreign key (quote_request_id) references public.quote_requests(id)\n  on delete cascade","-- AI and audit\nalter table public.ai_drafts\n  add constraint fk_ai_drafts_requested_by\n  foreign key (requested_by) references public.profiles(id)\n  on delete restrict,\n  add constraint fk_ai_drafts_reviewed_by\n  foreign key (reviewed_by) references public.profiles(id)\n  on delete set null","alter table public.audit_logs\n  add constraint fk_audit_logs_actor\n  foreign key (actor_id) references public.profiles(id)\n  on delete set null","-- Non-unique indexes for common joins, public filters, admin filters, and search.\ncreate index idx_profiles_role on public.profiles (role)","create index idx_profiles_is_active on public.profiles (is_active)","create index idx_profiles_deleted_at on public.profiles (deleted_at)","create index idx_profiles_email_trgm on public.profiles using gin (public.immutable_unaccent(lower(email)) gin_trgm_ops)","create index idx_media_assets_cloudinary_public_id on public.media_assets (cloudinary_public_id)","create index idx_media_assets_resource_status on public.media_assets (resource_type, status)","create index idx_media_assets_owner_context on public.media_assets (owner_context)","create index idx_media_assets_uploaded_by on public.media_assets (uploaded_by)","create index idx_media_assets_deleted_at on public.media_assets (deleted_at)","create index idx_media_asset_translations_media_locale on public.media_asset_translations (media_id, locale)","create index idx_site_setting_translations_locale on public.site_setting_translations (locale)","create index idx_social_links_enabled_sort on public.social_links (is_enabled, sort_order)","create index idx_quote_recipients_active on public.quote_recipients (is_active)","create index idx_content_pages_key_status on public.content_pages (key, status)","create index idx_content_pages_public on public.content_pages (key, published_at desc)\n  where status = 'published'::public.publish_status and deleted_at is null","create index idx_content_pages_deleted_at on public.content_pages (deleted_at)","create index idx_content_page_translations_page_locale on public.content_page_translations (page_id, locale)","create index idx_content_page_translations_locale_slug on public.content_page_translations (locale, slug)","create index idx_page_sections_page_sort on public.page_sections (page_id, sort_order)","create index idx_page_sections_enabled on public.page_sections (is_enabled)","create index idx_page_section_translations_section_locale on public.page_section_translations (section_id, locale)","create index idx_page_media_page_sort on public.page_media (page_id, sort_order)","create index idx_page_media_media on public.page_media (media_id)","create index idx_product_categories_parent on public.product_categories (parent_id)","create index idx_product_categories_group_key on public.product_categories (group_key)","create index idx_product_categories_status_sort on public.product_categories (status, sort_order)","create index idx_product_categories_public on public.product_categories (group_key, sort_order)\n  where status = 'published'::public.publish_status and deleted_at is null","create index idx_product_categories_deleted_at on public.product_categories (deleted_at)","create index idx_product_category_translations_category_locale on public.product_category_translations (category_id, locale)","create index idx_product_category_translations_locale_slug on public.product_category_translations (locale, slug)","create index idx_product_category_translations_name_trgm\n  on public.product_category_translations using gin (public.immutable_unaccent(lower(name)) gin_trgm_ops)","create index idx_products_category_status on public.products (category_id, status)","create index idx_products_featured_status on public.products (featured, status)","create index idx_products_price_range on public.products (price_min, price_max)","create index idx_products_created_at on public.products (created_at)","create index idx_products_deleted_at on public.products (deleted_at)","create index idx_products_public_sort on public.products (category_id, featured desc, sort_order, published_at desc)\n  where status = 'published'::public.publish_status and deleted_at is null","create index idx_products_brand_series_trgm\n  on public.products using gin (public.immutable_unaccent(lower(coalesce(brand_series, ''))) gin_trgm_ops)","create index idx_product_translations_product_locale on public.product_translations (product_id, locale)","create index idx_product_translations_locale_slug on public.product_translations (locale, slug)","create index idx_product_translations_search_text on public.product_translations using gin (search_text)","create index idx_product_translations_name_summary_trgm\n  on public.product_translations using gin (public.immutable_unaccent(lower(coalesce(name, '') || ' ' || coalesce(summary, '') || ' ' || coalesce(material, ''))) gin_trgm_ops)","create index idx_product_media_product_sort on public.product_media (product_id, sort_order)","create index idx_product_media_media on public.product_media (media_id)","create index idx_product_attribute_definitions_filterable_status on public.product_attribute_definitions (filterable, status)","create index idx_product_attribute_definitions_deleted_at on public.product_attribute_definitions (deleted_at)","create index idx_product_attribute_definition_translations_definition_locale on public.product_attribute_definition_translations (definition_id, locale)","create index idx_product_attribute_options_definition_status_sort on public.product_attribute_options (definition_id, status, sort_order)","create index idx_product_attribute_options_deleted_at on public.product_attribute_options (deleted_at)","create index idx_product_attribute_option_translations_option_locale on public.product_attribute_option_translations (option_id, locale)","create index idx_product_attribute_values_definition_option on public.product_attribute_values (attribute_definition_id, attribute_option_id)","create index idx_product_attribute_values_product_definition on public.product_attribute_values (product_id, attribute_definition_id)","create index idx_product_attribute_values_value_number on public.product_attribute_values (value_number)","create index idx_blog_categories_status_sort on public.blog_categories (status, sort_order)","create index idx_blog_categories_deleted_at on public.blog_categories (deleted_at)","create index idx_blog_category_translations_category_locale on public.blog_category_translations (category_id, locale)","create index idx_blog_category_translations_locale_slug on public.blog_category_translations (locale, slug)","create index idx_blog_category_translations_name_trgm\n  on public.blog_category_translations using gin (public.immutable_unaccent(lower(name)) gin_trgm_ops)","create index idx_blog_posts_category_status_published on public.blog_posts (category_id, status, published_at desc)","create index idx_blog_posts_author on public.blog_posts (author_id)","create index idx_blog_posts_featured_status on public.blog_posts (featured, status)","create index idx_blog_posts_deleted_at on public.blog_posts (deleted_at)","create index idx_blog_posts_public on public.blog_posts (published_at desc, featured desc)\n  where status = 'published'::public.publish_status and deleted_at is null","create index idx_blog_post_translations_post_locale on public.blog_post_translations (post_id, locale)","create index idx_blog_post_translations_locale_slug on public.blog_post_translations (locale, slug)","create index idx_blog_post_translations_search_text on public.blog_post_translations using gin (search_text)","create index idx_blog_post_translations_title_excerpt_trgm\n  on public.blog_post_translations using gin (public.immutable_unaccent(lower(coalesce(title, '') || ' ' || coalesce(excerpt, ''))) gin_trgm_ops)","create index idx_showrooms_status_sort on public.showrooms (status, sort_order)","create index idx_showrooms_deleted_at on public.showrooms (deleted_at)","create index idx_showrooms_public on public.showrooms (sort_order)\n  where status = 'published'::public.publish_status and deleted_at is null","create index idx_showroom_translations_showroom_locale on public.showroom_translations (showroom_id, locale)","create index idx_showroom_translations_name_address_trgm\n  on public.showroom_translations using gin (public.immutable_unaccent(lower(coalesce(name, '') || ' ' || coalesce(address, ''))) gin_trgm_ops)","create index idx_showroom_media_showroom_sort on public.showroom_media (showroom_id, sort_order)","create index idx_showroom_media_media on public.showroom_media (media_id)","create index idx_quote_requests_status_created on public.quote_requests (status, created_at desc)","create index idx_quote_requests_product on public.quote_requests (product_id)","create index idx_quote_requests_category on public.quote_requests (category_id)","create index idx_quote_requests_assigned_to on public.quote_requests (assigned_to)","create index idx_quote_requests_source_path on public.quote_requests (source_path)","create index idx_quote_requests_deleted_at on public.quote_requests (deleted_at)","create index idx_quote_requests_keyword_trgm\n  on public.quote_requests using gin (\n    public.immutable_unaccent(lower(coalesce(full_name, '') || ' ' || coalesce(phone, '') || ' ' || coalesce(email, '') || ' ' || coalesce(company, '') || ' ' || coalesce(service, '') || ' ' || coalesce(message, '') || ' ' || coalesce(admin_notes, ''))) gin_trgm_ops\n  )","create index idx_quote_request_events_quote_created on public.quote_request_events (quote_request_id, created_at)","create index idx_quote_request_events_actor on public.quote_request_events (actor_id)","create index idx_quote_notifications_quote_request on public.quote_notifications (quote_request_id)","create index idx_quote_notifications_status_created on public.quote_notifications (status, created_at)","create index idx_quote_notifications_provider_message_id on public.quote_notifications (provider_message_id)","create index idx_ai_drafts_target on public.ai_drafts (target_type, target_id)","create index idx_ai_drafts_requested_created on public.ai_drafts (requested_by, created_at)","create index idx_ai_drafts_status on public.ai_drafts (status)","create index idx_audit_logs_actor_created on public.audit_logs (actor_id, created_at)","create index idx_audit_logs_entity on public.audit_logs (entity_type, entity_id)","create index idx_audit_logs_action on public.audit_logs (action)","-- updated_at triggers.\ncreate trigger trg_profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at()","create trigger trg_media_assets_set_updated_at before update on public.media_assets for each row execute function public.set_updated_at()","create trigger trg_media_asset_translations_set_updated_at before update on public.media_asset_translations for each row execute function public.set_updated_at()","create trigger trg_site_settings_set_updated_at before update on public.site_settings for each row execute function public.set_updated_at()","create trigger trg_site_setting_translations_set_updated_at before update on public.site_setting_translations for each row execute function public.set_updated_at()","create trigger trg_social_links_set_updated_at before update on public.social_links for each row execute function public.set_updated_at()","create trigger trg_quote_recipients_set_updated_at before update on public.quote_recipients for each row execute function public.set_updated_at()","create trigger trg_content_pages_set_updated_at before update on public.content_pages for each row execute function public.set_updated_at()","create trigger trg_content_page_translations_set_updated_at before update on public.content_page_translations for each row execute function public.set_updated_at()","create trigger trg_page_sections_set_updated_at before update on public.page_sections for each row execute function public.set_updated_at()","create trigger trg_page_section_translations_set_updated_at before update on public.page_section_translations for each row execute function public.set_updated_at()","create trigger trg_page_media_set_updated_at before update on public.page_media for each row execute function public.set_updated_at()","create trigger trg_product_categories_set_updated_at before update on public.product_categories for each row execute function public.set_updated_at()","create trigger trg_product_category_translations_set_updated_at before update on public.product_category_translations for each row execute function public.set_updated_at()","create trigger trg_products_set_updated_at before update on public.products for each row execute function public.set_updated_at()","create trigger trg_product_translations_set_updated_at before update on public.product_translations for each row execute function public.set_updated_at()","create trigger trg_product_media_set_updated_at before update on public.product_media for each row execute function public.set_updated_at()","create trigger trg_product_attribute_definitions_set_updated_at before update on public.product_attribute_definitions for each row execute function public.set_updated_at()","create trigger trg_product_attribute_definition_translations_set_updated_at before update on public.product_attribute_definition_translations for each row execute function public.set_updated_at()","create trigger trg_product_attribute_options_set_updated_at before update on public.product_attribute_options for each row execute function public.set_updated_at()","create trigger trg_product_attribute_option_translations_set_updated_at before update on public.product_attribute_option_translations for each row execute function public.set_updated_at()","create trigger trg_product_attribute_values_set_updated_at before update on public.product_attribute_values for each row execute function public.set_updated_at()","create trigger trg_blog_categories_set_updated_at before update on public.blog_categories for each row execute function public.set_updated_at()","create trigger trg_blog_category_translations_set_updated_at before update on public.blog_category_translations for each row execute function public.set_updated_at()","create trigger trg_blog_posts_set_updated_at before update on public.blog_posts for each row execute function public.set_updated_at()","create trigger trg_blog_post_translations_set_updated_at before update on public.blog_post_translations for each row execute function public.set_updated_at()","create trigger trg_showrooms_set_updated_at before update on public.showrooms for each row execute function public.set_updated_at()","create trigger trg_showroom_translations_set_updated_at before update on public.showroom_translations for each row execute function public.set_updated_at()","create trigger trg_showroom_media_set_updated_at before update on public.showroom_media for each row execute function public.set_updated_at()","create trigger trg_quote_requests_set_updated_at before update on public.quote_requests for each row execute function public.set_updated_at()","create trigger trg_quote_notifications_set_updated_at before update on public.quote_notifications for each row execute function public.set_updated_at()","create trigger trg_ai_drafts_set_updated_at before update on public.ai_drafts for each row execute function public.set_updated_at()","-- Publish lifecycle triggers.\ncreate trigger trg_content_pages_set_publish_timestamps before insert or update on public.content_pages for each row execute function public.set_publish_timestamps()","create trigger trg_product_categories_set_publish_timestamps before insert or update on public.product_categories for each row execute function public.set_publish_timestamps()","create trigger trg_products_set_publish_timestamps before insert or update on public.products for each row execute function public.set_publish_timestamps()","create trigger trg_products_set_archive_timestamp before insert or update on public.products for each row execute function public.set_product_archive_timestamp()","create trigger trg_blog_categories_set_publish_timestamps before insert or update on public.blog_categories for each row execute function public.set_publish_timestamps()","create trigger trg_blog_posts_set_publish_timestamps before insert or update on public.blog_posts for each row execute function public.set_publish_timestamps()","create trigger trg_showrooms_set_publish_timestamps before insert or update on public.showrooms for each row execute function public.set_publish_timestamps()","-- Localized search-vector maintenance.\ncreate trigger trg_product_translations_search_text before insert or update\n  on public.product_translations\n  for each row execute function public.set_product_translation_search_text()","create trigger trg_blog_post_translations_search_text before insert or update\n  on public.blog_post_translations\n  for each row execute function public.set_blog_post_translation_search_text()","-- Append-only operational records.\ncreate trigger trg_quote_request_events_append_only before update or delete\n  on public.quote_request_events\n  for each row execute function public.prevent_update_delete()","create trigger trg_audit_logs_append_only before update or delete\n  on public.audit_logs\n  for each row execute function public.prevent_update_delete()",commit}	foreign_keys_indexes_triggers
0005	{"-- 0005_constraints_and_partial_uniques.sql\n-- Check constraints, unique/partial unique indexes, and publish validation.\n\nbegin","-- Unique and partial unique indexes.\ncreate unique index uq_profiles_email_lower on public.profiles (lower(email))","create unique index uq_media_assets_storage_identity\n  on public.media_assets (storage_provider, bucket, object_path)\n  where storage_provider = 'supabase_storage'::public.storage_provider\n    and bucket is not null\n    and object_path is not null\n    and deleted_at is null","create unique index uq_media_assets_cloudinary_public_id\n  on public.media_assets (cloudinary_public_id)\n  where storage_provider = 'cloudinary'::public.storage_provider\n    and cloudinary_public_id is not null\n    and deleted_at is null","create unique index uq_media_asset_translations_media_locale\n  on public.media_asset_translations (media_id, locale)","create unique index uq_site_settings_singleton_key on public.site_settings (singleton_key)","create unique index uq_site_setting_translations_settings_locale\n  on public.site_setting_translations (site_settings_id, locale)","create unique index uq_social_links_settings_platform\n  on public.social_links (site_settings_id, platform)","-- Active recipient uniqueness allows inactive historical duplicates.\ncreate unique index uq_quote_recipients_active_email\n  on public.quote_recipients (site_settings_id, lower(email))\n  where is_active","create unique index uq_content_pages_key on public.content_pages (key)","create unique index uq_content_page_translations_page_locale\n  on public.content_page_translations (page_id, locale)","create unique index uq_content_page_translations_locale_slug\n  on public.content_page_translations (locale, slug)","create unique index uq_page_sections_page_section_key\n  on public.page_sections (page_id, section_key)","create unique index uq_page_section_translations_section_locale\n  on public.page_section_translations (section_id, locale)","create unique index uq_page_media_page_media\n  on public.page_media (page_id, media_id)","create unique index uq_page_media_one_primary_per_page\n  on public.page_media (page_id)\n  where is_primary","create unique index uq_product_category_translations_category_locale\n  on public.product_category_translations (category_id, locale)","create unique index uq_product_category_translations_locale_slug\n  on public.product_category_translations (locale, slug)","create unique index uq_products_reference_code_active\n  on public.products (lower(reference_code))\n  where reference_code is not null and deleted_at is null","create unique index uq_product_translations_product_locale\n  on public.product_translations (product_id, locale)","create unique index uq_product_translations_locale_slug\n  on public.product_translations (locale, slug)","create unique index uq_product_media_product_media\n  on public.product_media (product_id, media_id)","create unique index uq_product_media_one_primary_per_product\n  on public.product_media (product_id)\n  where is_primary","create unique index uq_product_attribute_definitions_key_active\n  on public.product_attribute_definitions (lower(key))\n  where deleted_at is null","create unique index uq_product_attribute_definition_translations_definition_locale\n  on public.product_attribute_definition_translations (definition_id, locale)","create unique index uq_product_attribute_options_definition_key_active\n  on public.product_attribute_options (definition_id, lower(key))\n  where deleted_at is null","create unique index uq_product_attribute_option_translations_option_locale\n  on public.product_attribute_option_translations (option_id, locale)","create unique index uq_product_attribute_values_option\n  on public.product_attribute_values (product_id, attribute_definition_id, attribute_option_id)\n  where attribute_option_id is not null","create unique index uq_product_attribute_values_scalar\n  on public.product_attribute_values (product_id, attribute_definition_id)\n  where attribute_option_id is null","create unique index uq_blog_category_translations_category_locale\n  on public.blog_category_translations (category_id, locale)","create unique index uq_blog_category_translations_locale_slug\n  on public.blog_category_translations (locale, slug)","create unique index uq_blog_post_translations_post_locale\n  on public.blog_post_translations (post_id, locale)","create unique index uq_blog_post_translations_locale_slug\n  on public.blog_post_translations (locale, slug)","create unique index uq_showrooms_code_active\n  on public.showrooms (lower(code))\n  where code is not null and deleted_at is null","create unique index uq_showroom_translations_showroom_locale\n  on public.showroom_translations (showroom_id, locale)","create unique index uq_showroom_media_showroom_media\n  on public.showroom_media (showroom_id, media_id)","create unique index uq_showroom_media_one_primary_per_showroom\n  on public.showroom_media (showroom_id)\n  where is_primary","-- Basic domain checks.\nalter table public.profiles\n  add constraint chk_profiles_email_shape\n  check (email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$'),\n  add constraint chk_profiles_full_name_not_blank\n  check (public.compact_text(full_name) is not null)","alter table public.media_assets\n  add constraint chk_media_assets_positive_size\n  check (size_bytes > 0),\n  add constraint chk_media_assets_dimensions\n  check (\n    (width is null or width > 0)\n    and (height is null or height > 0)\n    and (duration_seconds is null or duration_seconds >= 0)\n  ),\n  add constraint chk_media_assets_provider_identity\n  check (\n    (\n      storage_provider = 'supabase_storage'::public.storage_provider\n      and public.compact_text(bucket) is not null\n      and public.compact_text(object_path) is not null\n    )\n    or (\n      storage_provider = 'cloudinary'::public.storage_provider\n      and public.compact_text(cloudinary_public_id) is not null\n    )\n  ),\n  add constraint chk_media_assets_public_url_http\n  check (public_url ~* '^https?://')","alter table public.site_settings\n  add constraint chk_site_settings_singleton_default\n  check (singleton_key = 'default'),\n  add constraint chk_site_settings_contact_email\n  check (contact_email is null or contact_email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$'),\n  add constraint chk_site_settings_quote_sender_email\n  check (quote_sender_email is null or quote_sender_email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$')","alter table public.social_links\n  add constraint chk_social_links_url_http\n  check (url ~* '^https?://')","alter table public.quote_recipients\n  add constraint chk_quote_recipients_email\n  check (email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$')","alter table public.content_pages\n  add constraint chk_content_pages_key_not_blank\n  check (public.compact_text(key) is not null),\n  add constraint chk_content_pages_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.content_page_translations\n  add constraint chk_content_page_translations_slug_not_blank\n  check (public.compact_text(slug) is not null),\n  add constraint chk_content_page_translations_title_not_blank\n  check (public.compact_text(title) is not null)","alter table public.page_sections\n  add constraint chk_page_sections_keys_not_blank\n  check (\n    public.compact_text(section_key) is not null\n    and public.compact_text(section_type) is not null\n  )","alter table public.page_section_translations\n  add constraint chk_page_section_translations_cta_href\n  check (\n    cta_href is null\n    or cta_href ~* '^(https?://|/|mailto:|tel:)'\n  )","alter table public.product_categories\n  add constraint chk_product_categories_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.product_category_translations\n  add constraint chk_product_category_translations_slug_not_blank\n  check (public.compact_text(slug) is not null),\n  add constraint chk_product_category_translations_name_not_blank\n  check (public.compact_text(name) is not null)","alter table public.products\n  add constraint chk_products_price_range\n  check (\n    (price_min is null or price_min >= 0)\n    and (price_max is null or price_max >= 0)\n    and (price_min is null or price_max is null or price_max >= price_min)\n  ),\n  add constraint chk_products_dimensions_non_negative\n  check (\n    (width is null or width >= 0)\n    and (depth is null or depth >= 0)\n    and (height is null or height >= 0)\n  ),\n  add constraint chk_products_currency_iso_like\n  check (currency ~ '^[A-Z]{3}$'),\n  add constraint chk_products_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.product_translations\n  add constraint chk_product_translations_slug_not_blank\n  check (public.compact_text(slug) is not null),\n  add constraint chk_product_translations_required_text\n  check (\n    public.compact_text(name) is not null\n    and public.compact_text(summary) is not null\n  )","alter table public.product_attribute_definitions\n  add constraint chk_product_attribute_definitions_key_not_blank\n  check (public.compact_text(key) is not null),\n  add constraint chk_product_attribute_definitions_data_type\n  check (data_type in ('text', 'number', 'boolean', 'option'))","alter table public.product_attribute_options\n  add constraint chk_product_attribute_options_key_not_blank\n  check (public.compact_text(key) is not null),\n  add constraint chk_product_attribute_options_swatch_hex\n  check (swatch_hex is null or swatch_hex ~* '^#[0-9a-f]{6}$')","alter table public.product_attribute_values\n  add constraint chk_product_attribute_values_shape\n  check (\n    (\n      attribute_option_id is not null\n      and value_text_vi is null\n      and value_text_en is null\n      and value_number is null\n      and value_boolean is null\n    )\n    or (\n      attribute_option_id is null\n      and (\n        (\n          (value_text_vi is not null or value_text_en is not null)\n          and value_number is null\n          and value_boolean is null\n        )\n        or (\n          value_number is not null\n          and value_text_vi is null\n          and value_text_en is null\n          and value_boolean is null\n        )\n        or (\n          value_boolean is not null\n          and value_text_vi is null\n          and value_text_en is null\n          and value_number is null\n        )\n      )\n    )\n  )","alter table public.blog_categories\n  add constraint chk_blog_categories_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.blog_category_translations\n  add constraint chk_blog_category_translations_slug_not_blank\n  check (public.compact_text(slug) is not null),\n  add constraint chk_blog_category_translations_name_not_blank\n  check (public.compact_text(name) is not null)","alter table public.blog_posts\n  add constraint chk_blog_posts_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.blog_post_translations\n  add constraint chk_blog_post_translations_slug_not_blank\n  check (public.compact_text(slug) is not null),\n  add constraint chk_blog_post_translations_required_text\n  check (\n    public.compact_text(title) is not null\n    and public.compact_text(excerpt) is not null\n  )","alter table public.showrooms\n  add constraint chk_showrooms_map_urls_https\n  check (\n    google_maps_embed_url ~* '^https://'\n    and google_maps_fallback_url ~* '^https://'\n  ),\n  add constraint chk_showrooms_coordinates\n  check (\n    (latitude is null or latitude between -90 and 90)\n    and (longitude is null or longitude between -180 and 180)\n  ),\n  add constraint chk_showrooms_published_at\n  check (status <> 'published'::public.publish_status or published_at is not null)","alter table public.showroom_translations\n  add constraint chk_showroom_translations_required_text\n  check (\n    public.compact_text(name) is not null\n    and public.compact_text(address) is not null\n  )","alter table public.quote_requests\n  add constraint chk_quote_requests_required_text\n  check (\n    public.compact_text(full_name) is not null\n    and public.compact_text(phone) is not null\n    and public.compact_text(message) is not null\n    and public.compact_text(source_path) is not null\n  ),\n  add constraint chk_quote_requests_phone_shape\n  check (phone ~ '^[0-9+().\\\\-\\\\s]{7,32}$'),\n  add constraint chk_quote_requests_email_shape\n  check (email is null or email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$'),\n  add constraint chk_quote_requests_source_path_shape\n  check (source_path like '/%'),\n  add constraint chk_quote_requests_source_url_http\n  check (source_url is null or source_url ~* '^https?://')","alter table public.quote_notifications\n  add constraint chk_quote_notifications_recipient_email\n  check (recipient_email ~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$'),\n  add constraint chk_quote_notifications_attempt_count\n  check (attempt_count >= 0)","alter table public.ai_drafts\n  add constraint chk_ai_drafts_prompt_type_not_blank\n  check (public.compact_text(prompt_type) is not null),\n  add constraint chk_ai_drafts_reviewed_when_final\n  check (status = 'draft'::public.ai_draft_status or reviewed_by is not null)","alter table public.audit_logs\n  add constraint chk_audit_logs_required_text\n  check (\n    public.compact_text(action) is not null\n    and public.compact_text(entity_type) is not null\n  )","-- Publish validation requiring both vi and en translations before publishing.\ncreate or replace function public.require_publish_translations()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  translation_count int;\nbegin\n  if new.status <> 'published'::public.publish_status then\n    return new;\n  end if;\n\n  case tg_table_name\n    when 'content_pages' then\n      select count(distinct locale)\n      into translation_count\n      from public.content_page_translations\n      where page_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(slug) is not null\n        and public.compact_text(title) is not null;\n\n    when 'product_categories' then\n      select count(distinct locale)\n      into translation_count\n      from public.product_category_translations\n      where category_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(slug) is not null\n        and public.compact_text(name) is not null;\n\n    when 'products' then\n      select count(distinct locale)\n      into translation_count\n      from public.product_translations\n      where product_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(slug) is not null\n        and public.compact_text(name) is not null\n        and public.compact_text(summary) is not null\n        and description_json is not null;\n\n    when 'product_attribute_definitions' then\n      select count(distinct locale)\n      into translation_count\n      from public.product_attribute_definition_translations\n      where definition_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(label) is not null;\n\n    when 'product_attribute_options' then\n      select count(distinct locale)\n      into translation_count\n      from public.product_attribute_option_translations\n      where option_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(label) is not null;\n\n    when 'blog_categories' then\n      select count(distinct locale)\n      into translation_count\n      from public.blog_category_translations\n      where category_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(slug) is not null\n        and public.compact_text(name) is not null;\n\n    when 'blog_posts' then\n      select count(distinct locale)\n      into translation_count\n      from public.blog_post_translations\n      where post_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(slug) is not null\n        and public.compact_text(title) is not null\n        and public.compact_text(excerpt) is not null\n        and body_json is not null;\n\n    when 'showrooms' then\n      select count(distinct locale)\n      into translation_count\n      from public.showroom_translations\n      where showroom_id = new.id\n        and locale in ('vi'::public.locale_code, 'en'::public.locale_code)\n        and public.compact_text(name) is not null\n        and public.compact_text(address) is not null;\n\n    else\n      translation_count := 2;\n  end case;\n\n  if translation_count < 2 then\n    raise exception 'Cannot publish %.% without required vi and en translations', tg_table_schema, tg_table_name\n      using errcode = '23514';\n  end if;\n\n  return new;\nend;\n$$","comment on function public.require_publish_translations() is\n  'Blocks publishing public content unless required vi and en translation rows exist. Also keep server-side publish validation in the CMS/API layer.'","create trigger trg_content_pages_require_publish_translations\n  before insert or update of status on public.content_pages\n  for each row execute function public.require_publish_translations()","create trigger trg_product_categories_require_publish_translations\n  before insert or update of status on public.product_categories\n  for each row execute function public.require_publish_translations()","create trigger trg_products_require_publish_translations\n  before insert or update of status on public.products\n  for each row execute function public.require_publish_translations()","create trigger trg_blog_categories_require_publish_translations\n  before insert or update of status on public.blog_categories\n  for each row execute function public.require_publish_translations()","create trigger trg_blog_posts_require_publish_translations\n  before insert or update of status on public.blog_posts\n  for each row execute function public.require_publish_translations()","create trigger trg_showrooms_require_publish_translations\n  before insert or update of status on public.showrooms\n  for each row execute function public.require_publish_translations()",commit}	constraints_and_partial_uniques
0006	{"-- 0006_rls_helper_functions.sql\n-- Supabase RLS helper functions. Keep these small and auditable.\n\nbegin","create or replace function public.current_profile_id()\nreturns uuid\nlanguage sql\nstable\nas $$\n  select auth.uid();\n$$","comment on function public.current_profile_id() is\n  'Returns the authenticated Supabase user/profile id from auth.uid().'","create or replace function public.is_service_role()\nreturns boolean\nlanguage sql\nstable\nas $$\n  select coalesce(auth.role(), '') = 'service_role';\n$$","comment on function public.is_service_role() is\n  'True when the current JWT role is Supabase service_role. Service role also bypasses RLS by default.'","create or replace function public.is_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1\n    from public.profiles p\n    where p.id = auth.uid()\n      and p.role = 'admin'::public.cms_role\n      and p.is_active\n      and p.deleted_at is null\n  );\n$$","comment on function public.is_admin() is\n  'True when the authenticated user has an active admin profile. SECURITY DEFINER avoids recursive profile RLS checks.'","create or replace function public.is_editor()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1\n    from public.profiles p\n    where p.id = auth.uid()\n      and p.role in ('admin'::public.cms_role, 'editor'::public.cms_role)\n      and p.is_active\n      and p.deleted_at is null\n  );\n$$","comment on function public.is_editor() is\n  'True when the authenticated user has an active admin or editor profile.'","create or replace function public.is_own_profile(profile_id uuid)\nreturns boolean\nlanguage sql\nstable\nas $$\n  select auth.uid() is not null and auth.uid() = profile_id;\n$$","comment on function public.is_own_profile(uuid) is\n  'True when a row belongs to the authenticated user.'","create or replace function public.can_manage_publishable_content()\nreturns boolean\nlanguage sql\nstable\nas $$\n  select public.is_editor() or public.is_service_role();\n$$","comment on function public.can_manage_publishable_content() is\n  'Role Model Option A helper: editor/admin/service can manage publishable content.'","create or replace function public.can_manage_private_admin_data()\nreturns boolean\nlanguage sql\nstable\nas $$\n  select public.is_admin() or public.is_service_role();\n$$","comment on function public.can_manage_private_admin_data() is\n  'Role Model Option A helper: admin/service can manage private leads, users, settings and audit data.'","revoke all on function public.current_profile_id() from public","revoke all on function public.is_service_role() from public","revoke all on function public.is_admin() from public","revoke all on function public.is_editor() from public","revoke all on function public.is_own_profile(uuid) from public","revoke all on function public.can_manage_publishable_content() from public","revoke all on function public.can_manage_private_admin_data() from public","grant execute on function public.current_profile_id() to anon, authenticated, service_role","grant execute on function public.is_service_role() to anon, authenticated, service_role","grant execute on function public.is_admin() to anon, authenticated, service_role","grant execute on function public.is_editor() to anon, authenticated, service_role","grant execute on function public.is_own_profile(uuid) to anon, authenticated, service_role","grant execute on function public.can_manage_publishable_content() to anon, authenticated, service_role","grant execute on function public.can_manage_private_admin_data() to anon, authenticated, service_role",commit}	rls_helper_functions
0007	{"-- 0007_rls_policies.sql\n-- Row Level Security grants and policies.\n-- Anonymous visitors do not receive direct table access. Public reads use the\n-- SECURITY DEFINER reader RPCs in 0008, and quote submission uses\n-- submit_quote_request(payload jsonb).\n\nbegin","-- Enable RLS on every application table.\nalter table public.profiles enable row level security","alter table public.media_assets enable row level security","alter table public.media_asset_translations enable row level security","alter table public.site_settings enable row level security","alter table public.site_setting_translations enable row level security","alter table public.social_links enable row level security","alter table public.quote_recipients enable row level security","alter table public.content_pages enable row level security","alter table public.content_page_translations enable row level security","alter table public.page_sections enable row level security","alter table public.page_section_translations enable row level security","alter table public.page_media enable row level security","alter table public.product_categories enable row level security","alter table public.product_category_translations enable row level security","alter table public.products enable row level security","alter table public.product_translations enable row level security","alter table public.product_media enable row level security","alter table public.product_attribute_definitions enable row level security","alter table public.product_attribute_definition_translations enable row level security","alter table public.product_attribute_options enable row level security","alter table public.product_attribute_option_translations enable row level security","alter table public.product_attribute_values enable row level security","alter table public.blog_categories enable row level security","alter table public.blog_category_translations enable row level security","alter table public.blog_posts enable row level security","alter table public.blog_post_translations enable row level security","alter table public.showrooms enable row level security","alter table public.showroom_translations enable row level security","alter table public.showroom_media enable row level security","alter table public.quote_requests enable row level security","alter table public.quote_request_events enable row level security","alter table public.quote_notifications enable row level security","alter table public.ai_drafts enable row level security","alter table public.audit_logs enable row level security","-- Baseline grants. RLS policies below still decide which rows are visible or mutable.\nrevoke all on table\n  public.profiles,\n  public.media_assets,\n  public.media_asset_translations,\n  public.site_settings,\n  public.site_setting_translations,\n  public.social_links,\n  public.quote_recipients,\n  public.content_pages,\n  public.content_page_translations,\n  public.page_sections,\n  public.page_section_translations,\n  public.page_media,\n  public.product_categories,\n  public.product_category_translations,\n  public.products,\n  public.product_translations,\n  public.product_media,\n  public.product_attribute_definitions,\n  public.product_attribute_definition_translations,\n  public.product_attribute_options,\n  public.product_attribute_option_translations,\n  public.product_attribute_values,\n  public.blog_categories,\n  public.blog_category_translations,\n  public.blog_posts,\n  public.blog_post_translations,\n  public.showrooms,\n  public.showroom_translations,\n  public.showroom_media,\n  public.quote_requests,\n  public.quote_request_events,\n  public.quote_notifications,\n  public.ai_drafts,\n  public.audit_logs\nfrom anon, authenticated","grant all on table\n  public.profiles,\n  public.media_assets,\n  public.media_asset_translations,\n  public.site_settings,\n  public.site_setting_translations,\n  public.social_links,\n  public.quote_recipients,\n  public.content_pages,\n  public.content_page_translations,\n  public.page_sections,\n  public.page_section_translations,\n  public.page_media,\n  public.product_categories,\n  public.product_category_translations,\n  public.products,\n  public.product_translations,\n  public.product_media,\n  public.product_attribute_definitions,\n  public.product_attribute_definition_translations,\n  public.product_attribute_options,\n  public.product_attribute_option_translations,\n  public.product_attribute_values,\n  public.blog_categories,\n  public.blog_category_translations,\n  public.blog_posts,\n  public.blog_post_translations,\n  public.showrooms,\n  public.showroom_translations,\n  public.showroom_media,\n  public.quote_requests,\n  public.quote_request_events,\n  public.quote_notifications,\n  public.ai_drafts,\n  public.audit_logs\nto service_role","grant select, insert, update on table public.profiles to authenticated","grant select, insert, update on table\n  public.media_assets,\n  public.content_pages,\n  public.product_categories,\n  public.products,\n  public.product_attribute_definitions,\n  public.product_attribute_options,\n  public.blog_categories,\n  public.blog_posts,\n  public.showrooms\nto authenticated","grant select, insert, update, delete on table\n  public.media_asset_translations,\n  public.content_page_translations,\n  public.page_sections,\n  public.page_section_translations,\n  public.page_media,\n  public.product_category_translations,\n  public.product_translations,\n  public.product_media,\n  public.product_attribute_definition_translations,\n  public.product_attribute_option_translations,\n  public.product_attribute_values,\n  public.blog_category_translations,\n  public.blog_post_translations,\n  public.showroom_translations,\n  public.showroom_media\nto authenticated","grant select, insert, update, delete on table\n  public.site_settings,\n  public.site_setting_translations,\n  public.social_links,\n  public.quote_recipients\nto authenticated","grant select, insert, update on table\n  public.quote_requests,\n  public.quote_notifications\nto authenticated","grant select, insert on table public.quote_request_events to authenticated","grant select, insert, update, delete on table public.ai_drafts to authenticated","grant select on table public.audit_logs to authenticated","-- Explicit service-role policies. Supabase service_role normally bypasses RLS,\n-- but these make intent clear if BYPASSRLS behavior is constrained later.\ncreate policy service_role_all on public.profiles for all to service_role using (true) with check (true)","create policy service_role_all on public.media_assets for all to service_role using (true) with check (true)","create policy service_role_all on public.media_asset_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.site_settings for all to service_role using (true) with check (true)","create policy service_role_all on public.site_setting_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.social_links for all to service_role using (true) with check (true)","create policy service_role_all on public.quote_recipients for all to service_role using (true) with check (true)","create policy service_role_all on public.content_pages for all to service_role using (true) with check (true)","create policy service_role_all on public.content_page_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.page_sections for all to service_role using (true) with check (true)","create policy service_role_all on public.page_section_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.page_media for all to service_role using (true) with check (true)","create policy service_role_all on public.product_categories for all to service_role using (true) with check (true)","create policy service_role_all on public.product_category_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.products for all to service_role using (true) with check (true)","create policy service_role_all on public.product_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.product_media for all to service_role using (true) with check (true)","create policy service_role_all on public.product_attribute_definitions for all to service_role using (true) with check (true)","create policy service_role_all on public.product_attribute_definition_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.product_attribute_options for all to service_role using (true) with check (true)","create policy service_role_all on public.product_attribute_option_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.product_attribute_values for all to service_role using (true) with check (true)","create policy service_role_all on public.blog_categories for all to service_role using (true) with check (true)","create policy service_role_all on public.blog_category_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.blog_posts for all to service_role using (true) with check (true)","create policy service_role_all on public.blog_post_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.showrooms for all to service_role using (true) with check (true)","create policy service_role_all on public.showroom_translations for all to service_role using (true) with check (true)","create policy service_role_all on public.showroom_media for all to service_role using (true) with check (true)","create policy service_role_all on public.quote_requests for all to service_role using (true) with check (true)","create policy service_role_all on public.quote_request_events for all to service_role using (true) with check (true)","create policy service_role_all on public.quote_notifications for all to service_role using (true) with check (true)","create policy service_role_all on public.ai_drafts for all to service_role using (true) with check (true)","create policy service_role_all on public.audit_logs for all to service_role using (true) with check (true)","-- Profiles: editor reads only self; admin manages all profile rows.\ncreate policy profiles_select_own_or_admin\n  on public.profiles for select to authenticated\n  using (public.is_own_profile(id) or public.is_admin())","create policy profiles_insert_admin\n  on public.profiles for insert to authenticated\n  with check (public.is_admin())","create policy profiles_update_admin\n  on public.profiles for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","-- Publishable/content/media tables: editors and admins manage publishable content.\ncreate policy media_assets_editor_select on public.media_assets for select to authenticated using (public.is_editor())","create policy media_assets_editor_insert on public.media_assets for insert to authenticated with check (public.is_editor())","create policy media_assets_editor_update on public.media_assets for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy media_asset_translations_editor_all on public.media_asset_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy content_pages_editor_select on public.content_pages for select to authenticated using (public.is_editor())","create policy content_pages_editor_insert on public.content_pages for insert to authenticated with check (public.is_editor())","create policy content_pages_editor_update on public.content_pages for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy content_page_translations_editor_all on public.content_page_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy page_sections_editor_all on public.page_sections for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy page_section_translations_editor_all on public.page_section_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy page_media_editor_all on public.page_media for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_categories_editor_select on public.product_categories for select to authenticated using (public.is_editor())","create policy product_categories_editor_insert on public.product_categories for insert to authenticated with check (public.is_editor())","create policy product_categories_editor_update on public.product_categories for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_category_translations_editor_all on public.product_category_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy products_editor_select on public.products for select to authenticated using (public.is_editor())","create policy products_editor_insert on public.products for insert to authenticated with check (public.is_editor())","create policy products_editor_update on public.products for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_translations_editor_all on public.product_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_media_editor_all on public.product_media for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_attribute_definitions_editor_select on public.product_attribute_definitions for select to authenticated using (public.is_editor())","create policy product_attribute_definitions_editor_insert on public.product_attribute_definitions for insert to authenticated with check (public.is_editor())","create policy product_attribute_definitions_editor_update on public.product_attribute_definitions for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_attribute_definition_translations_editor_all on public.product_attribute_definition_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_attribute_options_editor_select on public.product_attribute_options for select to authenticated using (public.is_editor())","create policy product_attribute_options_editor_insert on public.product_attribute_options for insert to authenticated with check (public.is_editor())","create policy product_attribute_options_editor_update on public.product_attribute_options for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_attribute_option_translations_editor_all on public.product_attribute_option_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy product_attribute_values_editor_all on public.product_attribute_values for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy blog_categories_editor_select on public.blog_categories for select to authenticated using (public.is_editor())","create policy blog_categories_editor_insert on public.blog_categories for insert to authenticated with check (public.is_editor())","create policy blog_categories_editor_update on public.blog_categories for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy blog_category_translations_editor_all on public.blog_category_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy blog_posts_editor_select on public.blog_posts for select to authenticated using (public.is_editor())","create policy blog_posts_editor_insert on public.blog_posts for insert to authenticated with check (public.is_editor())","create policy blog_posts_editor_update on public.blog_posts for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy blog_post_translations_editor_all on public.blog_post_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy showrooms_editor_select on public.showrooms for select to authenticated using (public.is_editor())","create policy showrooms_editor_insert on public.showrooms for insert to authenticated with check (public.is_editor())","create policy showrooms_editor_update on public.showrooms for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy showroom_translations_editor_all on public.showroom_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","create policy showroom_media_editor_all on public.showroom_media for all to authenticated using (public.is_editor()) with check (public.is_editor())","-- Settings: editors can read safe/admin UI settings but cannot mutate privileged rows.\ncreate policy site_settings_editor_read\n  on public.site_settings for select to authenticated\n  using (public.is_editor())","create policy site_settings_admin_insert\n  on public.site_settings for insert to authenticated\n  with check (public.is_admin())","create policy site_settings_admin_update\n  on public.site_settings for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","create policy site_settings_admin_delete\n  on public.site_settings for delete to authenticated\n  using (public.is_admin())","create policy site_setting_translations_editor_read\n  on public.site_setting_translations for select to authenticated\n  using (public.is_editor())","create policy site_setting_translations_admin_insert\n  on public.site_setting_translations for insert to authenticated\n  with check (public.is_admin())","create policy site_setting_translations_admin_update\n  on public.site_setting_translations for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","create policy site_setting_translations_admin_delete\n  on public.site_setting_translations for delete to authenticated\n  using (public.is_admin())","create policy social_links_editor_read\n  on public.social_links for select to authenticated\n  using (public.is_editor())","create policy social_links_admin_insert\n  on public.social_links for insert to authenticated\n  with check (public.is_admin())","create policy social_links_admin_update\n  on public.social_links for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","create policy social_links_admin_delete\n  on public.social_links for delete to authenticated\n  using (public.is_admin())","create policy quote_recipients_admin_all\n  on public.quote_recipients for all to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","-- Private quote lead workflow: editors have no direct access under Option A.\ncreate policy quote_requests_admin_select\n  on public.quote_requests for select to authenticated\n  using (public.is_admin())","create policy quote_requests_admin_insert\n  on public.quote_requests for insert to authenticated\n  with check (public.is_admin())","create policy quote_requests_admin_update\n  on public.quote_requests for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","create policy quote_request_events_admin_select\n  on public.quote_request_events for select to authenticated\n  using (public.is_admin())","create policy quote_request_events_admin_insert\n  on public.quote_request_events for insert to authenticated\n  with check (public.is_admin())","create policy quote_notifications_admin_select\n  on public.quote_notifications for select to authenticated\n  using (public.is_admin())","create policy quote_notifications_admin_insert\n  on public.quote_notifications for insert to authenticated\n  with check (public.is_admin())","create policy quote_notifications_admin_update\n  on public.quote_notifications for update to authenticated\n  using (public.is_admin())\n  with check (public.is_admin())","-- AI drafts: editors manage their own draft-only suggestions; admins manage all.\ncreate policy ai_drafts_select_admin_or_own\n  on public.ai_drafts for select to authenticated\n  using (public.is_admin() or requested_by = public.current_profile_id())","create policy ai_drafts_insert_own_editor\n  on public.ai_drafts for insert to authenticated\n  with check (\n    public.is_editor()\n    and requested_by = public.current_profile_id()\n  )","create policy ai_drafts_update_admin_or_own\n  on public.ai_drafts for update to authenticated\n  using (public.is_admin() or requested_by = public.current_profile_id())\n  with check (\n    public.is_admin()\n    or (\n      requested_by = public.current_profile_id()\n      and (reviewed_by is null or reviewed_by = public.current_profile_id())\n    )\n  )","create policy ai_drafts_delete_admin\n  on public.ai_drafts for delete to authenticated\n  using (public.is_admin())","-- Audit logs: admin can read. Writes should come from service-role trusted code.\ncreate policy audit_logs_admin_select\n  on public.audit_logs for select to authenticated\n  using (public.is_admin())",commit}	rls_policies
0008	{"-- 0008_public_admin_rpcs.sql\n-- Public reader RPCs, public quote submission RPC, and admin quote search RPC.\n\nbegin","create or replace function public.submit_quote_request(payload jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_locale_text text;\n  v_full_name text;\n  v_phone text;\n  v_email text;\n  v_company text;\n  v_service text;\n  v_message text;\n  v_source_path text;\n  v_source_url text;\n  v_product_id_text text;\n  v_category_id_text text;\n  v_product_id uuid;\n  v_category_id uuid;\n  v_quote_id uuid;\n  v_headers jsonb;\n  v_user_agent text;\n  v_ip_hash text;\nbegin\n  if payload is null or jsonb_typeof(payload) <> 'object' then\n    raise exception 'payload must be a JSON object' using errcode = '22023';\n  end if;\n\n  -- Honeypot submissions are treated as successful but are not persisted.\n  if public.compact_text(payload->>'honeypot') is not null then\n    return jsonb_build_object('submitted', true);\n  end if;\n\n  v_locale_text := coalesce(\n    public.compact_text(payload->>'preferred_locale'),\n    public.compact_text(payload->>'preferredLocale'),\n    public.compact_text(payload->>'locale'),\n    'vi'\n  );\n\n  if v_locale_text not in ('vi', 'en') then\n    raise exception 'preferred locale must be vi or en' using errcode = '22023';\n  end if;\n\n  v_full_name := left(public.compact_text(coalesce(payload->>'full_name', payload->>'fullName')), 160);\n  v_phone := left(public.compact_text(payload->>'phone'), 32);\n  v_email := lower(left(public.compact_text(payload->>'email'), 320));\n  v_company := left(public.compact_text(payload->>'company'), 180);\n  v_service := left(public.compact_text(payload->>'service'), 120);\n  v_message := left(public.compact_text(payload->>'message'), 5000);\n  v_source_path := left(public.compact_text(coalesce(payload->>'source_path', payload->>'sourcePath')), 2048);\n  v_source_url := left(public.compact_text(coalesce(payload->>'source_url', payload->>'sourceUrl')), 2048);\n  v_product_id_text := public.compact_text(coalesce(payload->>'product_id', payload->>'productId'));\n  v_category_id_text := public.compact_text(coalesce(payload->>'category_id', payload->>'categoryId'));\n\n  begin\n    v_headers := nullif(current_setting('request.headers', true), '')::jsonb;\n  exception\n    when others then\n      v_headers := '{}'::jsonb;\n  end;\n\n  v_user_agent := left(coalesce(\n    public.compact_text(v_headers->>'user-agent'),\n    public.compact_text(payload->>'user_agent'),\n    public.compact_text(payload->>'userAgent')\n  ), 1024);\n\n  -- Only trusted service-role callers should pass pre-hashed IP metadata.\n  if public.is_service_role() then\n    v_ip_hash := left(public.compact_text(coalesce(payload->>'ip_hash', payload->>'ipHash')), 128);\n  end if;\n\n  if v_full_name is null then\n    raise exception 'full_name is required' using errcode = '22023';\n  end if;\n\n  if v_phone is null or v_phone !~ '^[0-9+().\\\\-\\\\s]{7,32}$' then\n    raise exception 'valid phone is required' using errcode = '22023';\n  end if;\n\n  if v_email is not null and v_email !~* '^[A-Z0-9._%+\\\\-]+@[A-Z0-9.\\\\-]+\\\\.[A-Z]{2,}$' then\n    raise exception 'email is invalid' using errcode = '22023';\n  end if;\n\n  if v_message is null then\n    raise exception 'message is required' using errcode = '22023';\n  end if;\n\n  if v_source_path is null or v_source_path not like '/%' then\n    raise exception 'source_path is required and must start with /' using errcode = '22023';\n  end if;\n\n  if v_source_url is not null and v_source_url !~* '^https?://' then\n    raise exception 'source_url must be http or https' using errcode = '22023';\n  end if;\n\n  if v_product_id_text is not null then\n    if v_product_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then\n      raise exception 'product_id must be a UUID' using errcode = '22023';\n    end if;\n    v_product_id := v_product_id_text::uuid;\n\n    if not exists (\n      select 1\n      from public.products p\n      where p.id = v_product_id\n        and p.status = 'published'::public.publish_status\n        and p.deleted_at is null\n    ) then\n      raise exception 'product_id is not available for public quote submission' using errcode = '22023';\n    end if;\n  end if;\n\n  if v_category_id_text is not null then\n    if v_category_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then\n      raise exception 'category_id must be a UUID' using errcode = '22023';\n    end if;\n    v_category_id := v_category_id_text::uuid;\n\n    if not exists (\n      select 1\n      from public.product_categories c\n      where c.id = v_category_id\n        and c.status = 'published'::public.publish_status\n        and c.deleted_at is null\n    ) then\n      raise exception 'category_id is not available for public quote submission' using errcode = '22023';\n    end if;\n  end if;\n\n  insert into public.quote_requests (\n    full_name,\n    phone,\n    email,\n    company,\n    service,\n    message,\n    preferred_locale,\n    product_id,\n    category_id,\n    source_path,\n    source_url,\n    ip_hash,\n    user_agent,\n    status\n  )\n  values (\n    v_full_name,\n    v_phone,\n    v_email,\n    v_company,\n    v_service,\n    v_message,\n    v_locale_text::public.locale_code,\n    v_product_id,\n    v_category_id,\n    v_source_path,\n    v_source_url,\n    v_ip_hash,\n    v_user_agent,\n    'new'::public.quote_status\n  )\n  returning id into v_quote_id;\n\n  insert into public.quote_request_events (\n    quote_request_id,\n    actor_id,\n    old_status,\n    new_status,\n    note\n  )\n  values (\n    v_quote_id,\n    null,\n    null,\n    'new'::public.quote_status,\n    'Created by public quote submission RPC'\n  );\n\n  insert into public.quote_notifications (\n    quote_request_id,\n    recipient_email,\n    provider,\n    status\n  )\n  select\n    v_quote_id,\n    lower(qr.email),\n    'resend',\n    'pending'::public.notification_status\n  from public.quote_recipients qr\n  join public.site_settings ss on ss.id = qr.site_settings_id\n  where qr.is_active;\n\n  return jsonb_build_object('submitted', true);\nend;\n$$","comment on function public.submit_quote_request(jsonb) is\n  'Public-safe quote submission RPC. Validates/sanitizes input, inserts private quote_requests, queues pending notifications, and returns no lead id.'","create or replace function public.admin_quote_search(\n  p_status public.quote_status default null,\n  p_keyword text default null,\n  p_date_from timestamptz default null,\n  p_date_to timestamptz default null,\n  p_source_path text default null,\n  p_assigned_to uuid default null,\n  p_limit int default 50,\n  p_offset int default 0\n)\nreturns table (\n  id uuid,\n  full_name text,\n  phone text,\n  email text,\n  company text,\n  service text,\n  message text,\n  preferred_locale public.locale_code,\n  product_id uuid,\n  category_id uuid,\n  source_path text,\n  source_url text,\n  status public.quote_status,\n  assigned_to uuid,\n  admin_notes text,\n  created_at timestamptz,\n  updated_at timestamptz,\n  deleted_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_keyword text := public.compact_text(p_keyword);\n  v_limit int := least(greatest(coalesce(p_limit, 50), 1), 200);\n  v_offset int := greatest(coalesce(p_offset, 0), 0);\nbegin\n  if not public.can_manage_private_admin_data() then\n    raise exception 'admin access required' using errcode = '42501';\n  end if;\n\n  return query\n  select\n    qr.id,\n    qr.full_name,\n    qr.phone,\n    qr.email,\n    qr.company,\n    qr.service,\n    qr.message,\n    qr.preferred_locale,\n    qr.product_id,\n    qr.category_id,\n    qr.source_path,\n    qr.source_url,\n    qr.status,\n    qr.assigned_to,\n    qr.admin_notes,\n    qr.created_at,\n    qr.updated_at,\n    qr.deleted_at\n  from public.quote_requests qr\n  where qr.deleted_at is null\n    and (p_status is null or qr.status = p_status)\n    and (p_date_from is null or qr.created_at >= p_date_from)\n    and (p_date_to is null or qr.created_at < p_date_to)\n    and (p_source_path is null or qr.source_path = p_source_path)\n    and (p_assigned_to is null or qr.assigned_to = p_assigned_to)\n    and (\n      v_keyword is null\n      or public.immutable_unaccent(lower(concat_ws(\n        ' ',\n        qr.full_name,\n        qr.phone,\n        qr.email,\n        qr.company,\n        qr.service,\n        qr.message,\n        qr.admin_notes,\n        qr.source_path\n      ))) like '%' || public.immutable_unaccent(lower(v_keyword)) || '%'\n    )\n  order by qr.created_at desc\n  limit v_limit\n  offset v_offset;\nend;\n$$","comment on function public.admin_quote_search(public.quote_status, text, timestamptz, timestamptz, text, uuid, int, int) is\n  'Admin-only quote lead search by status, keyword, date range, source path, and assignee.'","create or replace function public.public_products(\n  p_locale public.locale_code default 'vi',\n  p_category_slug text default null,\n  p_group_key public.product_group_key default null,\n  p_q text default null,\n  p_price_min numeric default null,\n  p_price_max numeric default null,\n  p_attribute_filters jsonb default '{}'::jsonb,\n  p_featured boolean default null,\n  p_limit int default 24,\n  p_offset int default 0\n)\nreturns table (\n  id uuid,\n  reference_code text,\n  slug text,\n  name text,\n  summary text,\n  description_json jsonb,\n  material text,\n  price_display_text text,\n  dimension_display_text text,\n  category_id uuid,\n  category_slug text,\n  category_name text,\n  group_key public.product_group_key,\n  price_min numeric,\n  price_max numeric,\n  currency char(3),\n  width numeric,\n  depth numeric,\n  height numeric,\n  dimension_unit text,\n  brand_series text,\n  featured boolean,\n  published_at timestamptz,\n  primary_media jsonb,\n  media jsonb,\n  attributes jsonb\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\n  with params as (\n    select\n      public.compact_text(p_category_slug) as category_slug,\n      public.compact_text(p_q) as q,\n      coalesce(p_attribute_filters, '{}'::jsonb) as attribute_filters\n  ),\n  base as (\n    select\n      p.id,\n      p.reference_code,\n      pt.slug,\n      pt.name,\n      pt.summary,\n      pt.description_json,\n      pt.material,\n      pt.price_display_text,\n      pt.dimension_display_text,\n      pc.id as category_id,\n      pct.slug as category_slug,\n      pct.name as category_name,\n      coalesce(pc.group_key, parent_pc.group_key) as group_key,\n      p.price_min,\n      p.price_max,\n      p.currency,\n      p.width,\n      p.depth,\n      p.height,\n      p.dimension_unit,\n      p.brand_series,\n      p.featured,\n      p.published_at,\n      p.sort_order,\n      pt.search_text\n    from public.products p\n    join public.product_translations pt\n      on pt.product_id = p.id\n      and pt.locale = p_locale\n    join public.product_categories pc\n      on pc.id = p.category_id\n      and pc.status = 'published'::public.publish_status\n      and pc.deleted_at is null\n    left join public.product_categories parent_pc\n      on parent_pc.id = pc.parent_id\n      and parent_pc.status = 'published'::public.publish_status\n      and parent_pc.deleted_at is null\n    join public.product_category_translations pct\n      on pct.category_id = pc.id\n      and pct.locale = p_locale\n    cross join params params\n    where p.status = 'published'::public.publish_status\n      and p.deleted_at is null\n      and (params.category_slug is null or pct.slug = params.category_slug)\n      and (p_group_key is null or pc.group_key = p_group_key or parent_pc.group_key = p_group_key)\n      and (p_featured is null or p.featured = p_featured)\n      and (p_price_min is null or p.price_max is null or p.price_max >= p_price_min)\n      and (p_price_max is null or p.price_min is null or p.price_min <= p_price_max)\n      and (\n        params.q is null\n        or pt.search_text @@ plainto_tsquery('simple', public.immutable_unaccent(lower(params.q)))\n        or public.immutable_unaccent(lower(concat_ws(' ', p.reference_code, p.brand_series, pt.name, pt.summary, pct.name)))\n          like '%' || public.immutable_unaccent(lower(params.q)) || '%'\n      )\n      and (\n        params.attribute_filters = '{}'::jsonb\n        or not exists (\n          select 1\n          from jsonb_each(params.attribute_filters) filter_item(filter_key, filter_value)\n          where not exists (\n            select 1\n            from public.product_attribute_values pav\n            join public.product_attribute_definitions pad\n              on pad.id = pav.attribute_definition_id\n              and pad.deleted_at is null\n              and pad.status = 'published'::public.publish_status\n            left join public.product_attribute_options pao\n              on pao.id = pav.attribute_option_id\n              and pao.deleted_at is null\n              and pao.status = 'published'::public.publish_status\n            where pav.product_id = p.id\n              and pad.key = filter_item.filter_key\n              and (\n                (\n                  jsonb_typeof(filter_item.filter_value) = 'array'\n                  and exists (\n                    select 1\n                    from jsonb_array_elements_text(filter_item.filter_value) wanted(value)\n                    where wanted.value = coalesce(\n                      pao.key,\n                      pav.value_text_vi,\n                      pav.value_text_en,\n                      pav.value_number::text,\n                      pav.value_boolean::text\n                    )\n                  )\n                )\n                or (\n                  jsonb_typeof(filter_item.filter_value) <> 'array'\n                  and trim(both '\\"' from filter_item.filter_value::text) = coalesce(\n                    pao.key,\n                    pav.value_text_vi,\n                    pav.value_text_en,\n                    pav.value_number::text,\n                    pav.value_boolean::text\n                  )\n                )\n              )\n          )\n        )\n      )\n  )\n  select\n    b.id,\n    b.reference_code,\n    b.slug,\n    b.name,\n    b.summary,\n    b.description_json,\n    b.material,\n    b.price_display_text,\n    b.dimension_display_text,\n    b.category_id,\n    b.category_slug,\n    b.category_name,\n    b.group_key,\n    b.price_min,\n    b.price_max,\n    b.currency,\n    b.width,\n    b.depth,\n    b.height,\n    b.dimension_unit,\n    b.brand_series,\n    b.featured,\n    b.published_at,\n    (\n      select jsonb_build_object(\n        'id', ma.id,\n        'url', ma.public_url,\n        'resourceType', ma.resource_type,\n        'mimeType', ma.mime_type,\n        'width', ma.width,\n        'height', ma.height,\n        'altText', mat.alt_text,\n        'caption', mat.caption\n      )\n      from public.product_media pm\n      join public.media_assets ma\n        on ma.id = pm.media_id\n        and ma.status = 'active'::public.media_status\n        and ma.deleted_at is null\n      left join public.media_asset_translations mat\n        on mat.media_id = ma.id\n        and mat.locale = p_locale\n      where pm.product_id = b.id\n      order by pm.is_primary desc, pm.sort_order, pm.created_at\n      limit 1\n    ) as primary_media,\n    coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'id', ma.id,\n          'url', ma.public_url,\n          'resourceType', ma.resource_type,\n          'mimeType', ma.mime_type,\n          'width', ma.width,\n          'height', ma.height,\n          'isPrimary', pm.is_primary,\n          'context', pm.context,\n          'altText', mat.alt_text,\n          'caption', mat.caption\n        )\n        order by pm.is_primary desc, pm.sort_order, pm.created_at\n      )\n      from public.product_media pm\n      join public.media_assets ma\n        on ma.id = pm.media_id\n        and ma.status = 'active'::public.media_status\n        and ma.deleted_at is null\n      left join public.media_asset_translations mat\n        on mat.media_id = ma.id\n        and mat.locale = p_locale\n      where pm.product_id = b.id\n    ), '[]'::jsonb) as media,\n    coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'key', pad.key,\n          'label', padt.label,\n          'dataType', pad.data_type,\n          'optionKey', pao.key,\n          'optionLabel', paot.label,\n          'swatchHex', pao.swatch_hex,\n          'valueText', case when p_locale = 'vi' then pav.value_text_vi else pav.value_text_en end,\n          'valueNumber', pav.value_number,\n          'valueBoolean', pav.value_boolean\n        )\n        order by pad.sort_order, pao.sort_order\n      )\n      from public.product_attribute_values pav\n      join public.product_attribute_definitions pad\n        on pad.id = pav.attribute_definition_id\n        and pad.deleted_at is null\n        and pad.status = 'published'::public.publish_status\n      left join public.product_attribute_definition_translations padt\n        on padt.definition_id = pad.id\n        and padt.locale = p_locale\n      left join public.product_attribute_options pao\n        on pao.id = pav.attribute_option_id\n        and pao.deleted_at is null\n        and pao.status = 'published'::public.publish_status\n      left join public.product_attribute_option_translations paot\n        on paot.option_id = pao.id\n        and paot.locale = p_locale\n      where pav.product_id = b.id\n    ), '[]'::jsonb) as attributes\n  from base b\n  cross join params params\n  order by b.featured desc, b.sort_order, b.published_at desc, b.id\n  limit least(greatest(coalesce(p_limit, 24), 1), 100)\n  offset greatest(coalesce(p_offset, 0), 0);\n$$","comment on function public.public_products(public.locale_code, text, public.product_group_key, text, numeric, numeric, jsonb, boolean, int, int) is\n  'Public product reader. Returns only published, non-deleted products with localized fields, category, media, and attributes.'","create or replace function public.public_blog_posts(\n  p_locale public.locale_code default 'vi',\n  p_category_slug text default null,\n  p_q text default null,\n  p_featured boolean default null,\n  p_limit int default 12,\n  p_offset int default 0\n)\nreturns table (\n  id uuid,\n  slug text,\n  title text,\n  excerpt text,\n  body_json jsonb,\n  seo_title text,\n  seo_description text,\n  category_id uuid,\n  category_slug text,\n  category_name text,\n  author_id uuid,\n  author_name text,\n  featured boolean,\n  published_at timestamptz,\n  cover_media jsonb\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\n  with params as (\n    select\n      public.compact_text(p_category_slug) as category_slug,\n      public.compact_text(p_q) as q\n  )\n  select\n    bp.id,\n    bpt.slug,\n    bpt.title,\n    bpt.excerpt,\n    bpt.body_json,\n    bpt.seo_title,\n    bpt.seo_description,\n    bc.id as category_id,\n    bct.slug as category_slug,\n    bct.name as category_name,\n    bp.author_id,\n    prof.full_name as author_name,\n    bp.featured,\n    bp.published_at,\n    case\n      when ma.id is null then null\n      else jsonb_build_object(\n        'id', ma.id,\n        'url', ma.public_url,\n        'resourceType', ma.resource_type,\n        'mimeType', ma.mime_type,\n        'width', ma.width,\n        'height', ma.height,\n        'altText', mat.alt_text,\n        'caption', mat.caption\n      )\n    end as cover_media\n  from public.blog_posts bp\n  join public.blog_post_translations bpt\n    on bpt.post_id = bp.id\n    and bpt.locale = p_locale\n  join public.blog_categories bc\n    on bc.id = bp.category_id\n    and bc.status = 'published'::public.publish_status\n    and bc.deleted_at is null\n  join public.blog_category_translations bct\n    on bct.category_id = bc.id\n    and bct.locale = p_locale\n  join public.profiles prof\n    on prof.id = bp.author_id\n    and prof.is_active\n    and prof.deleted_at is null\n  left join public.media_assets ma\n    on ma.id = bp.cover_media_id\n    and ma.status = 'active'::public.media_status\n    and ma.deleted_at is null\n  left join public.media_asset_translations mat\n    on mat.media_id = ma.id\n    and mat.locale = p_locale\n  cross join params params\n  where bp.status = 'published'::public.publish_status\n    and bp.deleted_at is null\n    and (params.category_slug is null or bct.slug = params.category_slug)\n    and (p_featured is null or bp.featured = p_featured)\n    and (\n      params.q is null\n      or bpt.search_text @@ plainto_tsquery('simple', public.immutable_unaccent(lower(params.q)))\n      or public.immutable_unaccent(lower(concat_ws(' ', bpt.title, bpt.excerpt, bct.name, prof.full_name)))\n        like '%' || public.immutable_unaccent(lower(params.q)) || '%'\n    )\n  order by bp.featured desc, bp.published_at desc, bp.id\n  limit least(greatest(coalesce(p_limit, 12), 1), 50)\n  offset greatest(coalesce(p_offset, 0), 0);\n$$","comment on function public.public_blog_posts(public.locale_code, text, text, boolean, int, int) is\n  'Public blog reader. Returns only published, non-deleted posts with localized fields and safe media metadata.'","create or replace function public.public_showrooms(\n  p_locale public.locale_code default 'vi'\n)\nreturns table (\n  id uuid,\n  code text,\n  name text,\n  address text,\n  opening_hours text,\n  hotline text,\n  google_maps_embed_url text,\n  google_maps_fallback_url text,\n  latitude numeric,\n  longitude numeric,\n  primary_media jsonb,\n  media jsonb\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\n  select\n    s.id,\n    s.code,\n    st.name,\n    st.address,\n    st.opening_hours,\n    s.hotline,\n    s.google_maps_embed_url,\n    s.google_maps_fallback_url,\n    s.latitude,\n    s.longitude,\n    (\n      select jsonb_build_object(\n        'id', ma.id,\n        'url', ma.public_url,\n        'resourceType', ma.resource_type,\n        'mimeType', ma.mime_type,\n        'width', ma.width,\n        'height', ma.height,\n        'altText', mat.alt_text,\n        'caption', mat.caption\n      )\n      from public.showroom_media sm\n      join public.media_assets ma\n        on ma.id = sm.media_id\n        and ma.status = 'active'::public.media_status\n        and ma.deleted_at is null\n      left join public.media_asset_translations mat\n        on mat.media_id = ma.id\n        and mat.locale = p_locale\n      where sm.showroom_id = s.id\n      order by sm.is_primary desc, sm.sort_order, sm.created_at\n      limit 1\n    ) as primary_media,\n    coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'id', ma.id,\n          'url', ma.public_url,\n          'resourceType', ma.resource_type,\n          'mimeType', ma.mime_type,\n          'width', ma.width,\n          'height', ma.height,\n          'isPrimary', sm.is_primary,\n          'altText', mat.alt_text,\n          'caption', mat.caption\n        )\n        order by sm.is_primary desc, sm.sort_order, sm.created_at\n      )\n      from public.showroom_media sm\n      join public.media_assets ma\n        on ma.id = sm.media_id\n        and ma.status = 'active'::public.media_status\n        and ma.deleted_at is null\n      left join public.media_asset_translations mat\n        on mat.media_id = ma.id\n        and mat.locale = p_locale\n      where sm.showroom_id = s.id\n    ), '[]'::jsonb) as media\n  from public.showrooms s\n  join public.showroom_translations st\n    on st.showroom_id = s.id\n    and st.locale = p_locale\n  where s.status = 'published'::public.publish_status\n    and s.deleted_at is null\n  order by s.sort_order, s.created_at, s.id;\n$$","comment on function public.public_showrooms(public.locale_code) is\n  'Public showroom reader. Returns only published, non-deleted showrooms with localized address and safe map/media fields.'","revoke all on function public.submit_quote_request(jsonb) from public","revoke all on function public.admin_quote_search(public.quote_status, text, timestamptz, timestamptz, text, uuid, int, int) from public","revoke all on function public.public_products(public.locale_code, text, public.product_group_key, text, numeric, numeric, jsonb, boolean, int, int) from public","revoke all on function public.public_blog_posts(public.locale_code, text, text, boolean, int, int) from public","revoke all on function public.public_showrooms(public.locale_code) from public","grant execute on function public.submit_quote_request(jsonb) to anon, authenticated, service_role","grant execute on function public.admin_quote_search(public.quote_status, text, timestamptz, timestamptz, text, uuid, int, int) to authenticated, service_role","grant execute on function public.public_products(public.locale_code, text, public.product_group_key, text, numeric, numeric, jsonb, boolean, int, int) to anon, authenticated, service_role","grant execute on function public.public_blog_posts(public.locale_code, text, text, boolean, int, int) to anon, authenticated, service_role","grant execute on function public.public_showrooms(public.locale_code) to anon, authenticated, service_role",commit}	public_admin_rpcs
0009	{"-- 0009_optional_local_seed.sql\n-- Optional local-development seed data.\n-- This migration is a no-op unless the session sets:\n--   set app.seed_local = 'true';\n-- before running migrations locally.\n\nbegin","do $$\ndeclare\n  v_settings_id uuid;\n  v_home_page_id uuid;\n  v_about_page_id uuid;\n  v_wood_category_id uuid;\n  v_sanitary_category_id uuid;\n  v_product_id uuid;\n  v_showroom_id uuid;\n  v_author_id uuid;\n  v_blog_cat_id uuid;\n  v_product_2_id uuid;\n  v_product_3_id uuid;\n  v_product_4_id uuid;\n  v_blog_post_1_id uuid;\n  v_blog_post_2_id uuid;\n  v_blog_post_3_id uuid;\n  v_showroom_2_id uuid;\n  v_showroom_3_id uuid;\n\n  -- Fixed UUIDs for Media Assets\n  v_hero_media_id uuid := '00000000-0000-0000-0000-000000000101';\n  v_showroom_media_id uuid := '00000000-0000-0000-0000-000000000102';\n  v_woodwall_media_id uuid := '00000000-0000-0000-0000-000000000103';\n  v_sofa_media_id uuid := '00000000-0000-0000-0000-000000000104';\n  v_texture_media_id uuid := '00000000-0000-0000-0000-000000000105';\n  v_room_media_id uuid := '00000000-0000-0000-0000-000000000106';\n  v_table_media_id uuid := '00000000-0000-0000-0000-000000000107';\n  v_chair_media_id uuid := '00000000-0000-0000-0000-000000000108';\n  v_cabinet_media_id uuid := '00000000-0000-0000-0000-000000000109';\n  v_abouthero_media_id uuid := '00000000-0000-0000-0000-000000000110';\n  v_factory_media_id uuid := '00000000-0000-0000-0000-000000000111';\n  v_blog1_media_id uuid := '00000000-0000-0000-0000-000000000112';\n  v_blog2_media_id uuid := '00000000-0000-0000-0000-000000000113';\n  v_showroom2_media_id uuid := '00000000-0000-0000-0000-000000000114';\nbegin\n  -- Seed local data unconditionally in local development environment\n  -- if coalesce(current_setting('app.seed_local', true), 'false') <> 'true' then\n  --   return;\n  -- end if;\n\n  -- 1. SEED MEDIA ASSETS\n  insert into public.media_assets (id, storage_provider, cloudinary_public_id, public_url, resource_type, mime_type, format, size_bytes)\n  values\n    (v_hero_media_id, 'cloudinary', 'showroom/hero', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1234567890/showroom/hero.jpg', 'image', 'image/jpeg', 'jpg', 102400),\n    (v_showroom_media_id, 'cloudinary', 'showroom/showroom', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424086/showroom/showroom.jpg', 'image', 'image/jpeg', 'jpg', 102400),\n    (v_woodwall_media_id, 'cloudinary', 'showroom/woodWall', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424088/showroom/woodWall.png', 'image', 'image/png', 'png', 102400),\n    (v_sofa_media_id, 'cloudinary', 'showroom/sofa', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424089/showroom/sofa.jpg', 'image', 'image/jpeg', 'jpg', 102400),\n    (v_texture_media_id, 'cloudinary', 'showroom/texture', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424090/showroom/texture.jpg', 'image', 'image/jpeg', 'jpg', 102400),\n    (v_room_media_id, 'cloudinary', 'showroom/room', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424091/showroom/room.jpg', 'image', 'image/jpeg', 'jpg', 102400),\n    (v_table_media_id, 'cloudinary', 'showroom/table', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424092/showroom/table.png', 'image', 'image/png', 'png', 102400),\n    (v_chair_media_id, 'cloudinary', 'showroom/chair', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424093/showroom/chair.png', 'image', 'image/png', 'png', 102400),\n    (v_cabinet_media_id, 'cloudinary', 'showroom/cabinet', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424095/showroom/cabinet.png', 'image', 'image/png', 'png', 102400),\n    (v_abouthero_media_id, 'cloudinary', 'showroom/aboutHero', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424096/showroom/aboutHero.png', 'image', 'image/png', 'png', 102400),\n    (v_factory_media_id, 'cloudinary', 'showroom/factory', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424097/showroom/factory.png', 'image', 'image/png', 'png', 102400),\n    (v_blog1_media_id, 'cloudinary', 'showroom/blog1', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424098/showroom/blog1.png', 'image', 'image/png', 'png', 102400),\n    (v_blog2_media_id, 'cloudinary', 'showroom/blog2', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424100/showroom/blog2.png', 'image', 'image/png', 'png', 102400),\n    (v_showroom2_media_id, 'cloudinary', 'showroom/showroom2', 'https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424101/showroom/showroom2.png', 'image', 'image/png', 'png', 102400)\n  on conflict (id) do update\n  set\n    public_url = excluded.public_url,\n    updated_at = now();\n\n  -- 2. SEED SITE SETTINGS\n  insert into public.site_settings (\n    singleton_key,\n    contact_phone,\n    contact_email,\n    quote_sender_email,\n    logo_media_id,\n    favicon_media_id,\n    default_og_image_media_id\n  )\n  values (\n    'default',\n    '+84 000 000 000',\n    'hello@example.test',\n    'quotes@example.test',\n    v_hero_media_id,\n    v_hero_media_id,\n    v_hero_media_id\n  )\n  on conflict (singleton_key) do update\n  set\n    contact_phone = excluded.contact_phone,\n    contact_email = excluded.contact_email,\n    quote_sender_email = excluded.quote_sender_email,\n    logo_media_id = excluded.logo_media_id,\n    favicon_media_id = excluded.favicon_media_id,\n    default_og_image_media_id = excluded.default_og_image_media_id,\n    updated_at = now()\n  returning id into v_settings_id;\n\n  insert into public.site_setting_translations (\n    site_settings_id,\n    locale,\n    brand_name,\n    contact_address,\n    seo_default_title,\n    seo_default_description\n  )\n  values\n    (\n      v_settings_id,\n      'vi',\n      'Showroom Nội Thất Phương Đông',\n      'Địa chỉ demo cho phát triển local',\n      'Showroom Nội Thất Phương Đông',\n      'Nội thất gỗ và thiết bị vệ sinh cho không gian sống.'\n    ),\n    (\n      v_settings_id,\n      'en',\n      'Phuong Dong Interior Showroom',\n      'Local development demo address',\n      'Phuong Dong Interior Showroom',\n      'Wooden furniture and sanitary equipment for homes and projects.'\n    )\n  on conflict (site_settings_id, locale) do update\n  set\n    brand_name = excluded.brand_name,\n    contact_address = excluded.contact_address,\n    seo_default_title = excluded.seo_default_title,\n    seo_default_description = excluded.seo_default_description,\n    updated_at = now();\n\n  insert into public.social_links (\n    site_settings_id,\n    platform,\n    label,\n    url,\n    is_enabled,\n    share_enabled,\n    sort_order\n  )\n  values (\n    v_settings_id,\n    'facebook',\n    'Facebook',\n    'https://example.test/facebook',\n    true,\n    true,\n    10\n  )\n  on conflict (site_settings_id, platform) do update\n  set\n    label = excluded.label,\n    url = excluded.url,\n    is_enabled = excluded.is_enabled,\n    share_enabled = excluded.share_enabled,\n    sort_order = excluded.sort_order,\n    updated_at = now();\n\n  insert into public.quote_recipients (\n    site_settings_id,\n    email,\n    label,\n    is_active\n  )\n  select\n    v_settings_id,\n    'quotes@example.test',\n    'Local quote inbox',\n    true\n  where not exists (\n    select 1\n    from public.quote_recipients\n    where site_settings_id = v_settings_id\n      and lower(email) = 'quotes@example.test'\n      and is_active\n  );\n\n  insert into public.content_pages (key, status)\n  values ('home', 'draft')\n  on conflict (key) do update set updated_at = now()\n  returning id into v_home_page_id;\n\n  insert into public.content_pages (key, status)\n  values ('about', 'draft')\n  on conflict (key) do update set updated_at = now()\n  returning id into v_about_page_id;\n\n  insert into public.content_page_translations (\n    page_id,\n    locale,\n    slug,\n    title,\n    lead,\n    body_json,\n    seo_title,\n    seo_description\n  )\n  values\n    (\n      v_home_page_id,\n      'vi',\n      'trang-chu',\n      'Showroom Nội Thất Phương Đông',\n      'Nội thất gỗ và thiết bị vệ sinh cho nhà ở và công trình.',\n      '{}'::jsonb,\n      'Showroom Nội Thất Phương Đông',\n      'Trang demo local cho showroom nội thất và thiết bị vệ sinh.'\n    ),\n    (\n      v_home_page_id,\n      'en',\n      'home',\n      'Phuong Dong Interior Showroom',\n      'Wooden furniture and sanitary equipment for homes and projects.',\n      '{}'::jsonb,\n      'Phuong Dong Interior Showroom',\n      'Local demo homepage for furniture and sanitary equipment.'\n    ),\n    (\n      v_about_page_id,\n      'vi',\n      'gioi-thieu',\n      'Giới thiệu',\n      'Nội dung demo về tầm nhìn, sứ mệnh và năng lực.',\n      '{}'::jsonb,\n      'Giới thiệu',\n      'Thông tin demo về showroom.'\n    ),\n    (\n      v_about_page_id,\n      'en',\n      'about',\n      'About',\n      'Demo content for vision, mission and capabilities.',\n      '{}'::jsonb,\n      'About',\n      'Demo showroom information.'\n    )\n  on conflict (page_id, locale) do update\n  set\n    slug = excluded.slug,\n    title = excluded.title,\n    lead = excluded.lead,\n    body_json = excluded.body_json,\n    seo_title = excluded.seo_title,\n    seo_description = excluded.seo_description,\n    updated_at = now();\n\n  update public.content_pages\n  set status = 'published'\n  where id in (v_home_page_id, v_about_page_id);\n\n  -- 3. SEED PRODUCT CATEGORIES\n  select id into v_wood_category_id\n  from public.product_categories\n  where parent_id is null and group_key = 'wooden_furniture'\n  order by created_at\n  limit 1;\n\n  if v_wood_category_id is null then\n    insert into public.product_categories (group_key, status, sort_order, image_media_id)\n    values ('wooden_furniture', 'draft', 10, v_woodwall_media_id)\n    returning id into v_wood_category_id;\n  else\n    update public.product_categories\n    set image_media_id = v_woodwall_media_id\n    where id = v_wood_category_id;\n  end if;\n\n  select id into v_sanitary_category_id\n  from public.product_categories\n  where parent_id is null and group_key = 'sanitary_equipment'\n  order by created_at\n  limit 1;\n\n  if v_sanitary_category_id is null then\n    insert into public.product_categories (group_key, status, sort_order, image_media_id)\n    values ('sanitary_equipment', 'draft', 20, v_room_media_id)\n    returning id into v_sanitary_category_id;\n  else\n    update public.product_categories\n    set image_media_id = v_room_media_id\n    where id = v_sanitary_category_id;\n  end if;\n\n  insert into public.product_category_translations (\n    category_id,\n    locale,\n    slug,\n    name,\n    description,\n    seo_title,\n    seo_description\n  )\n  values\n    (\n      v_wood_category_id,\n      'vi',\n      'do-go-noi-that',\n      'Đồ gỗ nội thất',\n      'Nhóm sản phẩm đồ gỗ nội thất chất lượng cao.',\n      'Đồ gỗ nội thất',\n      'Danh mục đồ gỗ nội thất cao cấp Phương Đông.'\n    ),\n    (\n      v_wood_category_id,\n      'en',\n      'wooden-furniture',\n      'Wooden furniture',\n      'Premium wooden furniture collection.',\n      'Wooden furniture',\n      'Premium wooden furniture category by Phuong Dong.'\n    ),\n    (\n      v_sanitary_category_id,\n      'vi',\n      'thiet-bi-ve-sinh',\n      'Thiết bị vệ sinh',\n      'Nhóm sản phẩm thiết bị vệ sinh nhập khẩu cao cấp.',\n      'Thiết bị vệ sinh',\n      'Danh mục thiết bị vệ sinh showroom Phương Đông.'\n    ),\n    (\n      v_sanitary_category_id,\n      'en',\n      'sanitary-equipment',\n      'Sanitary equipment',\n      'Imported sanitary equipment collection.',\n      'Sanitary equipment',\n      'Premium sanitary equipment category by Phuong Dong.'\n    )\n  on conflict (category_id, locale) do update\n  set\n    slug = excluded.slug,\n    name = excluded.name,\n    description = excluded.description,\n    seo_title = excluded.seo_title,\n    seo_description = excluded.seo_description,\n    updated_at = now();\n\n  update public.product_categories\n  set status = 'published'\n  where id in (v_wood_category_id, v_sanitary_category_id);\n\n  -- Insert demo author profile\n  v_author_id := '00000000-0000-0000-0000-000000000001';\n  \n  insert into auth.users (id, instance_id, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, aud, role)\n  values (\n    v_author_id,\n    '00000000-0000-0000-0000-000000000000',\n    'author@phuongdong.vn',\n    extensions.crypt('password123', extensions.gen_salt('bf')),\n    now(),\n    '{\\"provider\\":\\"email\\",\\"providers\\":[\\"email\\"]}'::jsonb,\n    '{\\"full_name\\":\\"Tác Giả Demo\\"}'::jsonb,\n    'authenticated',\n    'authenticated'\n  )\n  on conflict (id) do nothing;\n\n  insert into public.profiles (id, email, full_name, role, is_active)\n  values (\n    v_author_id,\n    'author@phuongdong.vn',\n    'Tác Giả Demo',\n    'editor',\n    true\n  )\n  on conflict (id) do nothing;\n\n  -- 4. SEED PRODUCTS\n  -- Product 1: Sofa Curve Velour\n  select id into v_product_id\n  from public.products\n  where lower(reference_code) = 'pd-s2401'\n    and deleted_at is null\n  limit 1;\n\n  if v_product_id is null then\n    insert into public.products (category_id, reference_code, status, price_min, price_max, currency, brand_series, featured, sort_order)\n    values (v_wood_category_id, 'PD-S2401', 'draft', 45000000, 52000000, 'VND', 'Heritage Collection', true, 10)\n    returning id into v_product_id;\n  end if;\n\n  insert into public.product_translations (product_id, locale, slug, name, summary, description_json, material, price_display_text, dimension_display_text, seo_title, seo_description)\n  values\n    (v_product_id, 'vi', 'sofa-curve-velour', 'Sofa Curve Velour', 'Sofa cao cấp bọc vải Velour với đường cong tinh tế.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Gỗ sồi tự nhiên', '45,000,000 VND', '2400 x 950 x 850 mm', 'Sofa Curve Velour', 'Sofa cao cấp bọc vải Velour'),\n    (v_product_id, 'en', 'sofa-curve-velour', 'Sofa Curve Velour', 'Premium velour sofa with a soft curved silhouette.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Natural oak', '45,000,000 VND', '2400 x 950 x 850 mm', 'Sofa Curve Velour', 'Premium velour sofa')\n  on conflict (product_id, locale) do update set slug = excluded.slug, name = excluded.name, summary = excluded.summary, updated_at = now();\n\n  update public.products set status = 'published' where id = v_product_id;\n\n  -- Seed product media for Sofa Curve Velour\n  insert into public.product_media (product_id, media_id, context, is_primary, sort_order)\n  values\n    (v_product_id, v_sofa_media_id, 'gallery', true, 1),\n    (v_product_id, v_texture_media_id, 'gallery', false, 2),\n    (v_product_id, v_room_media_id, 'gallery', false, 3)\n  on conflict (product_id, media_id) do nothing;\n\n  -- Product 2: Bàn Trà Marble Round\n  select id into v_product_2_id\n  from public.products\n  where lower(reference_code) = 'pd-t2402'\n    and deleted_at is null\n  limit 1;\n\n  if v_product_2_id is null then\n    insert into public.products (category_id, reference_code, status, price_min, price_max, currency, brand_series, featured, sort_order)\n    values (v_wood_category_id, 'PD-T2402', 'draft', 12500000, 12500000, 'VND', 'Atelier Series', true, 20)\n    returning id into v_product_2_id;\n  end if;\n\n  insert into public.product_translations (product_id, locale, slug, name, summary, description_json, material, price_display_text, dimension_display_text, seo_title, seo_description)\n  values\n    (v_product_2_id, 'vi', 'ban-tra-marble-round', 'Bàn Trà Marble Round', 'Mặt đá marble Calacatta, chân gỗ walnut.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Đá marble', '12,500,000 VND', 'Đường kính 900 mm', 'Bàn Trà Marble Round', 'Bàn Trà Marble Round'),\n    (v_product_2_id, 'en', 'ban-tra-marble-round', 'Marble Round Coffee Table', 'Calacatta marble top and walnut base.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Marble', '12,500,000 VND', 'Diameter 900 mm', 'Marble Round Coffee Table', 'Marble Round Coffee Table')\n  on conflict (product_id, locale) do update set slug = excluded.slug, name = excluded.name, summary = excluded.summary, updated_at = now();\n\n  update public.products set status = 'published' where id = v_product_2_id;\n\n  -- Seed product media for Bàn Trà Marble Round\n  insert into public.product_media (product_id, media_id, context, is_primary, sort_order)\n  values\n    (v_product_2_id, v_table_media_id, 'gallery', true, 1),\n    (v_product_2_id, v_room_media_id, 'gallery', false, 2)\n  on conflict (product_id, media_id) do nothing;\n\n  -- Product 3: Kệ Tivi Minimalist Wood\n  select id into v_product_3_id\n  from public.products\n  where lower(reference_code) = 'pd-k2404'\n    and deleted_at is null\n  limit 1;\n\n  if v_product_3_id is null then\n    insert into public.products (category_id, reference_code, status, price_min, price_max, currency, brand_series, featured, sort_order)\n    values (v_wood_category_id, 'PD-K2404', 'draft', 22000000, 22000000, 'VND', 'Atelier Series', false, 30)\n    returning id into v_product_3_id;\n  end if;\n\n  insert into public.product_translations (product_id, locale, slug, name, summary, description_json, material, price_display_text, dimension_display_text, seo_title, seo_description)\n  values\n    (v_product_3_id, 'vi', 'ke-tivi-minimalist-wood', 'Kệ Tivi Minimalist Wood', 'Kệ tivi gỗ veneer tối màu với ngăn kéo giảm chấn.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Veneer', '22,000,000 VND', '2200 mm', 'Kệ Tivi Minimalist Wood', 'Kệ Tivi Minimalist Wood'),\n    (v_product_3_id, 'en', 'ke-tivi-minimalist-wood', 'Minimalist Wood TV Cabinet', 'Dark veneer TV cabinet with soft-close drawers.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Veneer', '22,000,000 VND', '2200 mm', 'Minimalist Wood TV Cabinet', 'Minimalist Wood TV Cabinet')\n  on conflict (product_id, locale) do update set slug = excluded.slug, name = excluded.name, summary = excluded.summary, updated_at = now();\n\n  update public.products set status = 'published' where id = v_product_3_id;\n\n  -- Seed product media for Kệ Tivi Minimalist Wood\n  insert into public.product_media (product_id, media_id, context, is_primary, sort_order)\n  values\n    (v_product_3_id, v_cabinet_media_id, 'gallery', true, 1)\n  on conflict (product_id, media_id) do nothing;\n\n  -- Product 4: Sen Tắm Mạ Vàng 24K\n  select id into v_product_4_id\n  from public.products\n  where lower(reference_code) = 'pd-b2405'\n    and deleted_at is null\n  limit 1;\n\n  if v_product_4_id is null then\n    insert into public.products (category_id, reference_code, status, price_min, price_max, currency, brand_series, featured, sort_order)\n    values (v_sanitary_category_id, 'PD-B2405', 'draft', 12500000, 12500000, 'VND', 'Wellness Collection', true, 40)\n    returning id into v_product_4_id;\n  end if;\n\n  insert into public.product_translations (product_id, locale, slug, name, summary, description_json, material, price_display_text, dimension_display_text, seo_title, seo_description)\n  values\n    (v_product_4_id, 'vi', 'sen-tam-ma-vang-24k', 'Sen Tắm Mạ Vàng 24K', 'Bộ sen tắm mạ vàng với van điều nhiệt.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Đồng thau', '12,500,000 VND', 'Tiêu chuẩn', 'Sen Tắm Mạ Vàng 24K', 'Sen Tắm Mạ Vàng 24K'),\n    (v_product_4_id, 'en', 'sen-tam-ma-vang-24k', '24K Gold Plated Shower Set', 'Gold plated shower set with thermostatic valve.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Brass', '12,500,000 VND', 'Standard', '24K Gold Plated Shower Set', '24K Gold Plated Shower Set')\n  on conflict (product_id, locale) do update set slug = excluded.slug, name = excluded.name, summary = excluded.summary, updated_at = now();\n\n  update public.products set status = 'published' where id = v_product_4_id;\n\n  -- Seed product media for Sen Tắm Mạ Vàng 24K\n  insert into public.product_media (product_id, media_id, context, is_primary, sort_order)\n  values\n    (v_product_4_id, v_room_media_id, 'gallery', true, 1)\n  on conflict (product_id, media_id) do nothing;\n\n\n  -- 5. SEED SHOWROOMS\n  -- Showroom 1: Hà Nội - Flagship Store\n  select id into v_showroom_id\n  from public.showrooms\n  where lower(code) = 'hn'\n    and deleted_at is null\n  limit 1;\n\n  if v_showroom_id is null then\n    insert into public.showrooms (code, hotline, google_maps_embed_url, google_maps_fallback_url, status, sort_order)\n    values ('HN', '1900 1234', 'https://www.google.com/maps/embed?pb=hanoi', 'https://www.google.com/maps', 'draft', 10)\n    returning id into v_showroom_id;\n  end if;\n\n  insert into public.showroom_translations (showroom_id, locale, name, address, opening_hours)\n  values\n    (v_showroom_id, 'vi', 'Hà Nội - Flagship Store', '123 Trần Duy Hưng, Cầu Giấy, Hà Nội', '08:00 - 20:00 hằng ngày'),\n    (v_showroom_id, 'en', 'Hanoi Flagship Store', '123 Tran Duy Hung, Cau Giay, Hanoi', '08:00 - 20:00 daily')\n  on conflict (showroom_id, locale) do update set name = excluded.name, address = excluded.address, updated_at = now();\n\n  update public.showrooms set status = 'published' where id = v_showroom_id;\n\n  -- Seed showroom media for HN Showroom\n  insert into public.showroom_media (showroom_id, media_id, is_primary, sort_order)\n  values\n    (v_showroom_id, v_showroom_media_id, true, 1)\n  on conflict (showroom_id, media_id) do nothing;\n\n  -- Showroom 2: TP. Hồ Chí Minh\n  select id into v_showroom_2_id\n  from public.showrooms\n  where lower(code) = 'hcm'\n    and deleted_at is null\n  limit 1;\n\n  if v_showroom_2_id is null then\n    insert into public.showrooms (code, hotline, google_maps_embed_url, google_maps_fallback_url, status, sort_order)\n    values ('HCM', '1900 5678', 'https://www.google.com/maps/embed?pb=hcm', 'https://www.google.com/maps', 'draft', 20)\n    returning id into v_showroom_2_id;\n  end if;\n\n  insert into public.showroom_translations (showroom_id, locale, name, address, opening_hours)\n  values\n    (v_showroom_2_id, 'vi', 'TP. Hồ Chí Minh', '456 Nguyễn Thị Minh Khai, Quận 1, TP. HCM', '08:30 - 19:30 hằng ngày'),\n    (v_showroom_2_id, 'en', 'Ho Chi Minh City', '456 Nguyen Thi Minh Khai, District 1, HCMC', '08:30 - 19:30 daily')\n  on conflict (showroom_id, locale) do update set name = excluded.name, address = excluded.address, updated_at = now();\n\n  update public.showrooms set status = 'published' where id = v_showroom_2_id;\n\n  -- Seed showroom media for HCM Showroom\n  insert into public.showroom_media (showroom_id, media_id, is_primary, sort_order)\n  values\n    (v_showroom_2_id, v_showroom2_media_id, true, 1)\n  on conflict (showroom_id, media_id) do nothing;\n\n  -- Showroom 3: Đà Nẵng Experience Studio\n  select id into v_showroom_3_id\n  from public.showrooms\n  where lower(code) = 'dn'\n    and deleted_at is null\n  limit 1;\n\n  if v_showroom_3_id is null then\n    insert into public.showrooms (code, hotline, google_maps_embed_url, google_maps_fallback_url, status, sort_order)\n    values ('DN', '1900 8888', 'https://www.google.com/maps/embed?pb=danang', 'https://www.google.com/maps', 'draft', 30)\n    returning id into v_showroom_3_id;\n  end if;\n\n  insert into public.showroom_translations (showroom_id, locale, name, address, opening_hours)\n  values\n    (v_showroom_3_id, 'vi', 'Đà Nẵng Experience Studio', '88 Nguyễn Văn Linh, Hải Châu, Đà Nẵng', '09:00 - 18:00'),\n    (v_showroom_3_id, 'en', 'Da Nang Experience Studio', '88 Nguyen Van Linh, Hai Chau, Da Nang', '09:00 - 18:00')\n  on conflict (showroom_id, locale) do update set name = excluded.name, address = excluded.address, updated_at = now();\n\n  update public.showrooms set status = 'published' where id = v_showroom_3_id;\n\n  -- Seed showroom media for DN Experience Studio\n  insert into public.showroom_media (showroom_id, media_id, is_primary, sort_order)\n  values\n    (v_showroom_3_id, v_room_media_id, true, 1)\n  on conflict (showroom_id, media_id) do nothing;\n\n\n  -- 6. SEED BLOG CATEGORIES & BLOG POSTS\n  -- Blog Category 1: Wood Knowledge\n  select id into v_blog_cat_id\n  from public.blog_categories\n  order by created_at\n  limit 1;\n\n  if v_blog_cat_id is null then\n    insert into public.blog_categories (status, sort_order)\n    values ('draft', 10)\n    returning id into v_blog_cat_id;\n  end if;\n\n  insert into public.blog_category_translations (category_id, locale, slug, name, description)\n  values\n    (v_blog_cat_id, 'vi', 'kien-thuc-do-go', 'Kiến thức đồ gỗ', 'Các bài viết tư vấn kỹ thuật chọn gỗ.'),\n    (v_blog_cat_id, 'en', 'wood-knowledge', 'Wood knowledge', 'Articles on wood material selection and tips.')\n  on conflict (category_id, locale) do update set name = excluded.name, slug = excluded.slug;\n\n  update public.blog_categories set status = 'published' where id = v_blog_cat_id;\n\n  -- Blog Post 1: Walnut Wood selection\n  select id into v_blog_post_1_id\n  from public.blog_posts\n  where deleted_at is null\n  order by created_at\n  limit 1;\n\n  if v_blog_post_1_id is null then\n    insert into public.blog_posts (category_id, author_id, status, featured, published_at, cover_media_id)\n    values (v_blog_cat_id, v_author_id, 'draft', true, now(), v_blog1_media_id)\n    returning id into v_blog_post_1_id;\n  else\n    update public.blog_posts\n    set cover_media_id = v_blog1_media_id\n    where id = v_blog_post_1_id;\n  end if;\n\n  insert into public.blog_post_translations (post_id, locale, slug, title, excerpt, body_json, seo_title, seo_description)\n  values\n    (v_blog_post_1_id, 'vi', 'bi-quyet-chon-go-oc-cho', 'Bí quyết chọn gỗ óc chó cho nội thất bền vững', 'Nhận biết vân gỗ, độ ẩm và quy trình xử lý bề mặt trước khi đầu tư.', '{\\"type\\":\\"doc\\",\\"content\\":[{\\"type\\":\\"paragraph\\",\\"content\\":[{\\"type\\":\\"text\\",\\"text\\":\\"Gỗ óc chó cao cấp luôn là lựa chọn hàng đầu...\\"}]}]}'::jsonb, 'Bí quyết chọn gỗ óc chó', 'Bí quyết chọn gỗ óc chó cho nội thất'),\n    (v_blog_post_1_id, 'en', 'bi-quyet-chon-go-oc-cho', 'How to choose walnut wood for lasting interiors', 'Understand grain, moisture and finishing process before investing.', '{\\"type\\":\\"doc\\",\\"content\\":[{\\"type\\":\\"paragraph\\",\\"content\\":[{\\"type\\":\\"text\\",\\"text\\":\\"Premium walnut wood is always a top choice...\\"}]}]}'::jsonb, 'How to choose walnut wood', 'How to choose walnut wood for interiors')\n  on conflict (post_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt;\n\n  update public.blog_posts set status = 'published' where id = v_blog_post_1_id;\n\n  -- Blog Post 2: Bathroom Trends\n  select id into v_blog_post_2_id\n  from public.blog_posts\n  where id <> v_blog_post_1_id and deleted_at is null\n  order by created_at\n  limit 1;\n\n  if v_blog_post_2_id is null then\n    insert into public.blog_posts (category_id, author_id, status, featured, published_at, cover_media_id)\n    values (v_blog_cat_id, v_author_id, 'draft', false, now() - interval '1 day', v_blog2_media_id)\n    returning id into v_blog_post_2_id;\n  else\n    update public.blog_posts\n    set cover_media_id = v_blog2_media_id\n    where id = v_blog_post_2_id;\n  end if;\n\n  insert into public.blog_post_translations (post_id, locale, slug, title, excerpt, body_json, seo_title, seo_description)\n  values\n    (v_blog_post_2_id, 'vi', 'xu-huong-phong-tam-2026', 'Xu hướng phòng tắm khách sạn trong nhà ở hiện đại', 'Các lớp vật liệu, ánh sáng và phụ kiện giúp phòng tắm trở thành nghỉ dưỡng.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Xu hướng phòng tắm khách sạn', 'Xu hướng phòng tắm khách sạn 2026'),\n    (v_blog_post_2_id, 'en', 'xu-huong-phong-tam-2026', 'Hotel-inspired bathroom trends for modern homes', 'Material layers, lighting and accessories that turn bathrooms into wellness spaces.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Hotel-inspired bathroom trends', 'Hotel-inspired bathroom trends')\n  on conflict (post_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt;\n\n  update public.blog_posts set status = 'published' where id = v_blog_post_2_id;\n\n  -- Blog Post 3: Tile Wood Stone layout\n  select id into v_blog_post_3_id\n  from public.blog_posts\n  where id not in (v_blog_post_1_id, v_blog_post_2_id) and deleted_at is null\n  order by created_at\n  limit 1;\n\n  if v_blog_post_3_id is null then\n    insert into public.blog_posts (category_id, author_id, status, featured, published_at, cover_media_id)\n    values (v_blog_cat_id, v_author_id, 'draft', false, now() - interval '2 days', v_texture_media_id)\n    returning id into v_blog_post_3_id;\n  else\n    update public.blog_posts\n    set cover_media_id = v_texture_media_id\n    where id = v_blog_post_3_id;\n  end if;\n\n  insert into public.blog_post_translations (post_id, locale, slug, title, excerpt, body_json, seo_title, seo_description)\n  values\n    (v_blog_post_3_id, 'vi', 'phoi-gach-go-va-da', 'Phối gạch, gỗ và đá để không gian có chiều sâu', 'Cách cân bằng bề mặt lạnh và ấm để không gian sang trọng nhưng vẫn gần gũi.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Phối gạch gỗ và đá', 'Phối gạch gỗ và đá'),\n    (v_blog_post_3_id, 'en', 'phoi-gach-go-va-da', 'Combining tile, wood and stone for visual depth', 'Balance cool and warm surfaces to keep spaces premium yet welcoming.', '{\\"type\\":\\"doc\\",\\"content\\":[]}'::jsonb, 'Combining tile wood and stone', 'Combining tile wood and stone')\n  on conflict (post_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt;\n\n  update public.blog_posts set status = 'published' where id = v_blog_post_3_id;\n\nend\n$$",commit}	optional_local_seed
20260607	{"-- 20260607_gemini_settings.sql\n-- Create integration_secrets table with RLS and admin-only policies.\n\nbegin","create table if not exists public.integration_secrets (\n  id uuid primary key default extensions.gen_random_uuid(),\n  key_name text unique not null,\n  encrypted_value text not null,\n  masked_hint text not null,\n  is_active boolean not null default true,\n  updated_by uuid references public.profiles(id),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","comment on table public.integration_secrets is\n  'Integration secrets stored securely with AES-256-GCM encryption at the application level.'","-- Attach the updated_at trigger\ncreate trigger set_updated_at\n  before update on public.integration_secrets\n  for each row\n  execute function public.set_updated_at()","-- Enable RLS\nalter table public.integration_secrets enable row level security","-- Deny default permissions to public roles\nrevoke all on table public.integration_secrets from anon, authenticated","-- Grant all permissions to service_role\ngrant all on table public.integration_secrets to service_role","-- Allow select for Admins only\ncreate policy \\"Admin select secrets\\" on public.integration_secrets\n  for select to authenticated using (\n    exists (\n      select 1 from public.profiles\n      where profiles.id = auth.uid()\n        and profiles.role = 'admin'::public.cms_role\n    )\n  )","-- Allow modify for Admins only\ncreate policy \\"Admin write secrets\\" on public.integration_secrets\n  for all to authenticated using (\n    exists (\n      select 1 from public.profiles\n      where profiles.id = auth.uid()\n        and profiles.role = 'admin'::public.cms_role\n    )\n  ) with check (\n    exists (\n      select 1 from public.profiles\n      where profiles.id = auth.uid()\n        and profiles.role = 'admin'::public.cms_role\n    )\n  )",commit}	gemini_settings
20260608	{begin,"-- Grant select to public (anon & authenticated) roles\ngrant select on table public.product_categories to anon, authenticated","grant select on table public.product_category_translations to anon, authenticated","grant select on table public.blog_categories to anon, authenticated","grant select on table public.blog_category_translations to anon, authenticated","-- Create public select policies for product categories\ncreate policy product_categories_public_select on public.product_categories\n  for select to anon, authenticated\n  using (status = 'published' and deleted_at is null)","create policy product_category_translations_public_select on public.product_category_translations\n  for select to anon, authenticated\n  using (true)","-- Create public select policies for blog categories\ncreate policy blog_categories_public_select on public.blog_categories\n  for select to anon, authenticated\n  using (status = 'published' and deleted_at is null)","create policy blog_category_translations_public_select on public.blog_category_translations\n  for select to anon, authenticated\n  using (true)",commit}	public_categories_rls
20260610	{"-- migration file: supabase/migrations/20260610_promotions.sql\n-- Database DDL for promotions and product promotion settings.\n\nbegin","-- Create promotions table\ncreate table if not exists public.promotions (\n  id uuid primary key default extensions.gen_random_uuid(),\n  code text unique not null,\n  discount_percentage numeric(5,2),\n  status public.publish_status not null default 'draft',\n  start_at timestamptz,\n  end_at timestamptz,\n  created_by uuid,\n  updated_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","comment on table public.promotions is\n  'Promotion campaigns or discount events. Manageable by editors and admins.'","-- Create promotion translations table\ncreate table if not exists public.promotion_translations (\n  id uuid primary key default extensions.gen_random_uuid(),\n  promotion_id uuid not null references public.promotions(id) on delete cascade,\n  locale public.locale_code not null,\n  title text not null,\n  description text,\n  seo_title text,\n  seo_description text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique(promotion_id, locale)\n)","comment on table public.promotion_translations is\n  'Localized translation fields for promotions.'","-- Add columns to products table for direct promotion association\nalter table public.products\nadd column if not exists promotion_id uuid references public.promotions(id) on delete set null,\nadd column if not exists promo_price_min numeric(12,2),\nadd column if not exists promo_price_max numeric(12,2)","-- Enable RLS\nalter table public.promotions enable row level security","alter table public.promotion_translations enable row level security","-- Baseline grants\nrevoke all on table\n  public.promotions,\n  public.promotion_translations\nfrom anon, authenticated","grant all on table\n  public.promotions,\n  public.promotion_translations\nto service_role","grant select, insert, update on table public.promotions to authenticated","grant select, insert, update, delete on table public.promotion_translations to authenticated","-- Service role policies\ncreate policy service_role_all on public.promotions for all to service_role using (true) with check (true)","create policy service_role_all on public.promotion_translations for all to service_role using (true) with check (true)","-- Editor/Admin RLS Policies (can CRUD publishable promotions)\ncreate policy promotions_editor_select on public.promotions for select to authenticated using (public.is_editor())","create policy promotions_editor_insert on public.promotions for insert to authenticated with check (public.is_editor())","create policy promotions_editor_update on public.promotions for update to authenticated using (public.is_editor()) with check (public.is_editor())","create policy promotion_translations_editor_all on public.promotion_translations for all to authenticated using (public.is_editor()) with check (public.is_editor())","-- Public reader RPC for promotions\ncreate or replace function public.public_promotions(\n  p_locale public.locale_code default 'vi'\n)\nreturns table (\n  id uuid,\n  code text,\n  discount_percentage numeric,\n  start_at timestamptz,\n  end_at timestamptz,\n  title text,\n  description text\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\n  select\n    p.id,\n    p.code,\n    p.discount_percentage,\n    p.start_at,\n    p.end_at,\n    pt.title,\n    pt.description\n  from public.promotions p\n  join public.promotion_translations pt\n    on pt.promotion_id = p.id\n    and pt.locale = p_locale\n  where p.status = 'published'::public.publish_status\n    and p.deleted_at is null\n    and (p.start_at is null or p.start_at <= now())\n    and (p.end_at is null or p.end_at >= now())\n  order by p.created_at desc;\n$$","comment on function public.public_promotions(public.locale_code) is\n  'Public promotions reader. Returns active published promotions with localized title/description.'","grant execute on function public.public_promotions(public.locale_code) to anon, authenticated, service_role","-- Seed default promotions\ninsert into public.promotions (id, code, discount_percentage, status)\nvalues \n  ('11111111-1111-1111-1111-111111111111', 'heritage-walnut-combo', 15.00, 'published'),\n  ('22222222-2222-2222-2222-222222222222', 'wellness-bath-set', 18.00, 'published'),\n  ('33333333-3333-3333-3333-333333333333', 'porcelain-surface-pack', 20.00, 'published')\non conflict (code) do nothing","insert into public.promotion_translations (promotion_id, locale, title, description)\nvalues\n  ('11111111-1111-1111-1111-111111111111', 'vi', 'Không Gian Phòng Khách Walnut Heritage', 'Tinh tuyển gỗ óc chó tự nhiên cho căn hộ cao cấp'),\n  ('11111111-1111-1111-1111-111111111111', 'en', 'Heritage Walnut Living Room Package', 'Curated natural walnut for premium apartments'),\n  ('22222222-2222-2222-2222-222222222222', 'vi', 'Trọn Bộ Thiết Bị Phòng Tắm Wellness', 'Không gian spa thư giãn nhập khẩu chính hãng tiêu chuẩn Châu Âu'),\n  ('22222222-2222-2222-2222-222222222222', 'en', 'Wellness Master Bathroom Suite', 'Relaxing spa suite with European standards'),\n  ('33333333-3333-3333-3333-333333333333', 'vi', 'Gói Gạch Ốp Lát Toàn Diện Grand Surface', 'Vật liệu cao cấp hoàn thiện bề mặt sang trọng, bền vững'),\n  ('33333333-3333-3333-3333-333333333333', 'en', 'Grand Surface Porcelain Tile Package', 'Premium materials for luxury and durable surfaces')\non conflict (promotion_id, locale) do nothing",commit}	promotions
20260613000001	{"-- 20260613_brands_and_enhancements.sql\r\n-- Add Brands entity and enhance Promotions, Quote Requests for business operations\r\n\r\nbegin","-- ============================================================================\r\n-- 1. CREATE BRANDS TABLE (Thương hiệu)\r\n-- ============================================================================\r\n\r\ncreate table if not exists public.brands (\r\n  id uuid primary key default extensions.gen_random_uuid(),\r\n  logo_media_id uuid,\r\n  origin text,\r\n  status public.publish_status not null default 'draft',\r\n  sort_order int not null default 0,\r\n  created_by uuid,\r\n  updated_by uuid,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now(),\r\n  published_at timestamptz,\r\n  deleted_at timestamptz\r\n)","comment on table public.brands is\r\n  'Brand partners (Kohler, Grohe, TOTO, etc.). Used for product filtering and mega menu display.'","create table if not exists public.brand_translations (\r\n  id uuid primary key default extensions.gen_random_uuid(),\r\n  brand_id uuid not null,\r\n  locale public.locale_code not null,\r\n  name text not null,\r\n  description text,\r\n  seo_title text,\r\n  seo_description text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","comment on table public.brand_translations is\r\n  'Bilingual translations for brand names and descriptions.'","-- ============================================================================\r\n-- 2. ADD BRAND_ID TO PRODUCTS\r\n-- ============================================================================\r\n\r\n-- Add brand_id column to products table\r\nalter table public.products \r\n  add column if not exists brand_id uuid","comment on column public.products.brand_id is\r\n  'Foreign key to brands table. Replaces free-text brand_series field.'","-- ============================================================================\r\n-- 3. ENHANCE PROMOTIONS FOR COMBO SUPPORT\r\n-- ============================================================================\r\n\r\n-- Add columns for combo display\r\nalter table public.promotions\r\n  add column if not exists cover_media_id uuid,\r\n  add column if not exists combo_price numeric(12,2),\r\n  add column if not exists original_price numeric(12,2),\r\n  add column if not exists metadata_jsonb jsonb default '{}'::jsonb","comment on column public.promotions.cover_media_id is\r\n  'Cover image for combo promotion display.'","comment on column public.promotions.combo_price is\r\n  'Special combo package price.'","comment on column public.promotions.original_price is\r\n  'Original total price before discount for combo.'","comment on column public.promotions.metadata_jsonb is\r\n  'Flexible JSON storage for combo product lists and other display configurations.'","-- Create promotion targets table for flexible assignment\r\ncreate table if not exists public.promotion_targets (\r\n  id uuid primary key default extensions.gen_random_uuid(),\r\n  promotion_id uuid not null,\r\n  target_type text not null check (target_type in ('product', 'category', 'brand', 'all')),\r\n  target_id uuid,\r\n  created_at timestamptz not null default now()\r\n)","comment on table public.promotion_targets is\r\n  'Many-to-many relationship: promotions can apply to specific products, categories, brands, or all items.'","-- ============================================================================\r\n-- 4. ENHANCE QUOTE_REQUESTS FOR SALES WORKFLOW\r\n-- ============================================================================\r\n\r\n-- Add columns for lead management\r\nalter table public.quote_requests\r\n  add column if not exists assigned_to uuid,\r\n  add column if not exists sales_notes text,\r\n  add column if not exists snapshot_price numeric(12,2),\r\n  add column if not exists snapshot_promo_price numeric(12,2)","comment on column public.quote_requests.assigned_to is\r\n  'Sales staff assigned to handle this lead (references profiles.id).'","comment on column public.quote_requests.sales_notes is\r\n  'Internal notes from sales team about consultation progress.'","comment on column public.quote_requests.snapshot_price is\r\n  'Product price snapshot at the time customer submitted quote request.'","comment on column public.quote_requests.snapshot_promo_price is\r\n  'Promotional price snapshot at the time customer submitted quote request.'","-- Create quote status history table for audit trail\r\ncreate table if not exists public.quote_status_history (\r\n  id uuid primary key default extensions.gen_random_uuid(),\r\n  quote_request_id uuid not null,\r\n  old_status public.quote_status,\r\n  new_status public.quote_status not null,\r\n  changed_by uuid,\r\n  changed_at timestamptz not null default now(),\r\n  notes text\r\n)","comment on table public.quote_status_history is\r\n  'Audit trail for quote request status changes (new -> contacted -> quoted -> won/lost).'","-- ============================================================================\r\n-- 5. ADD FOREIGN KEY CONSTRAINTS\r\n-- ============================================================================\r\n\r\n-- Brands foreign keys\r\nalter table public.brands\r\n  add constraint fk_brands_logo_media\r\n    foreign key (logo_media_id) references public.media_assets(id) on delete set null,\r\n  add constraint fk_brands_created_by\r\n    foreign key (created_by) references public.profiles(id) on delete set null,\r\n  add constraint fk_brands_updated_by\r\n    foreign key (updated_by) references public.profiles(id) on delete set null","alter table public.brand_translations\r\n  add constraint fk_brand_translations_brand\r\n    foreign key (brand_id) references public.brands(id) on delete cascade,\r\n  add constraint uq_brand_translations_brand_locale\r\n    unique (brand_id, locale)","-- Products brand_id foreign key\r\nalter table public.products\r\n  add constraint fk_products_brand\r\n    foreign key (brand_id) references public.brands(id) on delete set null","-- Promotions foreign keys\r\nalter table public.promotions\r\n  add constraint fk_promotions_cover_media\r\n    foreign key (cover_media_id) references public.media_assets(id) on delete set null","alter table public.promotion_targets\r\n  add constraint fk_promotion_targets_promotion\r\n    foreign key (promotion_id) references public.promotions(id) on delete cascade","-- Quote requests foreign keys\r\ndo $$\r\nbegin\r\n  if not exists (\r\n    select 1 from pg_constraint where conname = 'fk_quote_requests_assigned_to'\r\n  ) then\r\n    alter table public.quote_requests\r\n      add constraint fk_quote_requests_assigned_to\r\n        foreign key (assigned_to) references public.profiles(id) on delete set null;\r\n  end if;\r\nend $$","do $$\r\nbegin\r\n  if not exists (\r\n    select 1 from pg_constraint where conname = 'fk_quote_status_history_quote'\r\n  ) then\r\n    alter table public.quote_status_history\r\n      add constraint fk_quote_status_history_quote\r\n        foreign key (quote_request_id) references public.quote_requests(id) on delete cascade;\r\n  end if;\r\nend $$","do $$\r\nbegin\r\n  if not exists (\r\n    select 1 from pg_constraint where conname = 'fk_quote_status_history_changed_by'\r\n  ) then\r\n    alter table public.quote_status_history\r\n      add constraint fk_quote_status_history_changed_by\r\n        foreign key (changed_by) references public.profiles(id) on delete set null;\r\n  end if;\r\nend $$","-- ============================================================================\r\n-- 6. CREATE INDEXES FOR PERFORMANCE\r\n-- ============================================================================\r\n\r\ncreate index if not exists idx_brands_status on public.brands(status) where deleted_at is null","create index if not exists idx_brands_sort_order on public.brands(sort_order)","create index if not exists idx_brand_translations_brand_id on public.brand_translations(brand_id)","create index if not exists idx_brand_translations_locale on public.brand_translations(locale)","create index if not exists idx_products_brand_id on public.products(brand_id) where deleted_at is null","create index if not exists idx_promotion_targets_promotion on public.promotion_targets(promotion_id)","create index if not exists idx_promotion_targets_type_id on public.promotion_targets(target_type, target_id)","create index if not exists idx_quote_requests_assigned_to on public.quote_requests(assigned_to)","create index if not exists idx_quote_status_history_quote on public.quote_status_history(quote_request_id)","-- ============================================================================\r\n-- 7. ADD RLS POLICIES FOR BRANDS\r\n-- ============================================================================\r\n\r\nalter table public.brands enable row level security","alter table public.brand_translations enable row level security","-- Public read access for published brands\r\ncreate policy \\"Public read published brands\\"\r\n  on public.brands for select\r\n  using (status = 'published' and deleted_at is null)","create policy \\"Public read brand translations\\"\r\n  on public.brand_translations for select\r\n  using (\r\n    exists (\r\n      select 1 from public.brands b\r\n      where b.id = brand_translations.brand_id\r\n        and b.status = 'published'\r\n        and b.deleted_at is null\r\n    )\r\n  )","-- Admin/Editor full access\r\ncreate policy \\"Editors can manage brands\\"\r\n  on public.brands for all\r\n  using (\r\n    exists (\r\n      select 1 from public.profiles p\r\n      where p.id = auth.uid()\r\n        and p.is_active = true\r\n        and p.role in ('admin', 'editor')\r\n    )\r\n  )","create policy \\"Editors can manage brand translations\\"\r\n  on public.brand_translations for all\r\n  using (\r\n    exists (\r\n      select 1 from public.profiles p\r\n      where p.id = auth.uid()\r\n 