id,\n  code text,\n  discount_percentage numeric,\n  combo_price numeric\n)\nlanguage plpgsql\nsecurity definer\nas $$\nbegin\n  return query\n  select distinct\n    p.id as promotion_id,\n    p.code,\n    p.discount_percentage,\n    p.combo_price\n  from public.promotions p\n  left join public.promotion_targets pt on pt.promotion_id = p.id\n  left join public.product_promotions pp on pp.promotion_id = p.id\n  where p.status = 'published'\n    and p.deleted_at is null\n    and (p.start_at is null or p.start_at <= now())\n    and (p.end_at is null or p.end_at >= now())\n    and (\n      pt.target_type = 'all'\n      or (pt.target_type = 'product' and pt.target_id = p_product_id)\n      or (pt.target_type = 'category' and pt.target_id in (\n        select category_id from public.products where id = p_product_id\n      ))\n      or (pt.target_type = 'brand' and pt.target_id in (\n        select brand_id from public.products where id = p_product_id\n      ))\n      or pp.product_id = p_product_id\n    );\nend;\n$$",commit}	product_promotions
20260614000002	{"-- Migration: Update public_products RPC to support brand_slug and has_discount filters\n-- Date: 20260614\n-- Purpose: Fix audit v3 item #7 — product catalog server-side filtering now includes brand and discount\n\n-- Update the public_products RPC function to support brand_slug and has_discount params\nCREATE OR REPLACE FUNCTION public_products(\n  p_locale          text      DEFAULT 'vi',\n  p_category_slug   text      DEFAULT NULL,\n  p_group_key       text      DEFAULT NULL,\n  p_q               text      DEFAULT NULL,\n  p_price_min       numeric   DEFAULT NULL,\n  p_price_max       numeric   DEFAULT NULL,\n  p_attribute_filters jsonb   DEFAULT '{}',\n  p_featured        boolean   DEFAULT NULL,\n  p_limit           int       DEFAULT 24,\n  p_offset          int       DEFAULT 0,\n  p_brand_slug      text      DEFAULT NULL,\n  p_has_discount    boolean   DEFAULT NULL\n)\nRETURNS TABLE (\n  id                  uuid,\n  reference_code      text,\n  slug                text,\n  name                text,\n  summary             text,\n  description_json    jsonb,\n  material            text,\n  price_display_text  text,\n  dimension_display_text text,\n  category_id         uuid,\n  category_slug       text,\n  category_name       text,\n  group_key           text,\n  price_min           numeric,\n  price_max           numeric,\n  currency            text,\n  brand_id            uuid,\n  brand_name          text,\n  brand_series        text,\n  featured            boolean,\n  published_at        timestamptz,\n  primary_media       jsonb,\n  media               jsonb,\n  specs               jsonb,\n  attributes          jsonb\n)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nAS $$\nDECLARE\n  v_locale text := COALESCE(p_locale, 'vi');\nBEGIN\n  RETURN QUERY\n  SELECT\n    p.id,\n    p.reference_code,\n    COALESCE(pt.slug, p.id::text)            AS slug,\n    COALESCE(pt.name, '')                    AS name,\n    COALESCE(pt.summary, '')                 AS summary,\n    COALESCE(pt.description_json, '{}'::jsonb) AS description_json,\n    COALESCE(pt.material, '')                AS material,\n    COALESCE(pt.price_display_text, '')      AS price_display_text,\n    COALESCE(pt.dimension_display_text, '')  AS dimension_display_text,\n    pc.id                                    AS category_id,\n    COALESCE(pc.slug, '')                    AS category_slug,\n    COALESCE(pct.name, pc.slug)              AS category_name,\n    p.group_key,\n    p.price_min,\n    p.price_max,\n    p.currency,\n    b.id                                     AS brand_id,\n    COALESCE(bt.name, b.slug)                AS brand_name,\n    COALESCE(p.brand_series, '')             AS brand_series,\n    p.featured,\n    p.published_at,\n    -- Primary media\n    (\n      SELECT jsonb_build_object('url', ma.public_url, 'altText', pm_a.alt_text)\n      FROM product_media pm_a\n      JOIN media_assets ma ON ma.id = pm_a.media_id\n      WHERE pm_a.product_id = p.id AND pm_a.is_primary = true\n      LIMIT 1\n    )                                        AS primary_media,\n    -- All media\n    COALESCE((\n      SELECT jsonb_agg(jsonb_build_object('url', ma2.public_url, 'altText', pm2.alt_text) ORDER BY pm2.sort_order)\n      FROM product_media pm2\n      JOIN media_assets ma2 ON ma2.id = pm2.media_id\n      WHERE pm2.product_id = p.id\n    ), '[]'::jsonb)                          AS media,\n    -- Specs\n    COALESCE(p.specs, '{}'::jsonb)           AS specs,\n    -- Attributes\n    COALESCE((\n      SELECT jsonb_agg(jsonb_build_object('key', pa.attribute_key, 'value', pa.attribute_value))\n      FROM product_attributes pa\n      WHERE pa.product_id = p.id\n    ), '[]'::jsonb)                          AS attributes\n  FROM products p\n  JOIN product_translations pt\n    ON pt.product_id = p.id\n    AND pt.locale = v_locale\n  JOIN product_categories pc\n    ON pc.id = p.category_id\n  LEFT JOIN product_category_translations pct\n    ON pct.category_id = pc.id\n    AND pct.locale = v_locale\n  LEFT JOIN brands b\n    ON b.id = p.brand_id\n  LEFT JOIN brand_translations bt\n    ON bt.brand_id = b.id\n    AND bt.locale = v_locale\n  WHERE\n    p.status = 'published'\n    AND p.deleted_at IS NULL\n    AND pc.deleted_at IS NULL\n    -- Category filter\n    AND (p_category_slug IS NULL OR pc.slug = p_category_slug)\n    -- Group key filter\n    AND (p_group_key IS NULL OR p.group_key = p_group_key)\n    -- Brand filter\n    AND (p_brand_slug IS NULL OR b.slug = p_brand_slug)\n    -- Full-text search\n    AND (\n      p_q IS NULL\n      OR pt.name ILIKE '%' || p_q || '%'\n      OR pt.summary ILIKE '%' || p_q || '%'\n      OR p.reference_code ILIKE '%' || p_q || '%'\n    )\n    -- Price range\n    AND (p_price_min IS NULL OR p.price_min >= p_price_min)\n    AND (p_price_max IS NULL OR p.price_max <= p_price_max)\n    -- Featured filter\n    AND (p_featured IS NULL OR p.featured = p_featured)\n    -- Has discount filter: product has at least one active promotion\n    AND (\n      p_has_discount IS NULL\n      OR (\n        p_has_discount = true\n        AND EXISTS (\n          SELECT 1\n          FROM product_promotions pp2\n          JOIN promotions promo ON promo.id = pp2.promotion_id\n          WHERE pp2.product_id = p.id\n            AND promo.status = 'published'\n            AND (promo.start_at IS NULL OR promo.start_at <= now())\n            AND (promo.end_at IS NULL OR promo.end_at >= now())\n        )\n      )\n    )\n    -- Attribute filters (JSONB)\n    AND (\n      p_attribute_filters IS NULL\n      OR p_attribute_filters = '{}'::jsonb\n      OR (\n        SELECT bool_and(\n          EXISTS (\n            SELECT 1 FROM product_attributes pa2\n            WHERE pa2.product_id = p.id\n              AND pa2.attribute_key = kv.key\n              AND pa2.attribute_value = kv.value\n          )\n        )\n        FROM jsonb_each_text(p_attribute_filters) kv\n      )\n    )\n  ORDER BY p.featured DESC, p.published_at DESC NULLS LAST\n  LIMIT p_limit\n  OFFSET p_offset;\nEND;\n$$","-- Grant execute\nGRANT EXECUTE ON FUNCTION public_products(text, text, text, text, numeric, numeric, jsonb, boolean, int, int, text, boolean) TO anon, authenticated","-- RLS policy to allow read on media_assets for uploaded assets\n-- (Ensure authenticated users can insert their own media assets)\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies\n    WHERE tablename = 'media_assets'\n      AND policyname = 'Editor or admin can insert media assets'\n  ) THEN\n    CREATE POLICY \\"Editor or admin can insert media assets\\"\n      ON media_assets FOR INSERT\n      WITH CHECK (\n        EXISTS (\n          SELECT 1 FROM profiles\n          WHERE profiles.id = auth.uid()\n            AND profiles.role IN ('admin', 'editor')\n        )\n      );\n  END IF;\nEND $$","-- Allow authenticated users to read their own media assets\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies\n    WHERE tablename = 'media_assets'\n      AND policyname = 'Auth users can read media assets'\n  ) THEN\n    CREATE POLICY \\"Auth users can read media assets\\"\n      ON media_assets FOR SELECT\n      USING (auth.uid() IS NOT NULL);\n  END IF;\nEND $$"}	products_rpc_brand_discount
20260614000003	{"-- Migration: Quote Status Workflow Enhancement\n-- Date: 20260614\n-- Purpose: Add quote_status_logs table and update quote_requests status enum\n\n-- 1. Add quote_status_logs table to track status change history\nCREATE TABLE IF NOT EXISTS quote_status_logs (\n  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),\n  quote_id    uuid        NOT NULL REFERENCES quote_requests(id) ON DELETE CASCADE,\n  from_status text,\n  to_status   text        NOT NULL,\n  changed_by  uuid        REFERENCES profiles(id) ON DELETE SET NULL,\n  note        text,\n  created_at  timestamptz NOT NULL DEFAULT now()\n)","-- 2. Add indexes for efficient querying\nCREATE INDEX IF NOT EXISTS idx_quote_status_logs_quote_id ON quote_status_logs(quote_id)","CREATE INDEX IF NOT EXISTS idx_quote_status_logs_created_at ON quote_status_logs(created_at DESC)","-- 3. Add assigned_to and admin_notes columns to quote_requests if not already present\nALTER TABLE quote_requests\n  ADD COLUMN IF NOT EXISTS assigned_to  text,\n  ADD COLUMN IF NOT EXISTS admin_notes  text","-- 4. RLS policies for quote_status_logs — admin only\nALTER TABLE quote_status_logs ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Admin can read all quote status logs\\"\n  ON quote_status_logs FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n        AND profiles.role = 'admin'\n    )\n  )","CREATE POLICY \\"Admin can insert quote status logs\\"\n  ON quote_status_logs FOR INSERT\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n        AND profiles.role = 'admin'\n    )\n  )","-- 5. RPC function: update_quote_status — atomically updates status + logs the change\nCREATE OR REPLACE FUNCTION update_quote_status(\n  p_quote_id    uuid,\n  p_new_status  text,\n  p_note        text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  v_old_status text;\n  v_user_id    uuid;\n  v_allowed_statuses text[] := ARRAY['new', 'processing', 'contacted', 'qualified', 'closed', 'cancelled', 'spam'];\nBEGIN\n  -- Verify caller is admin\n  SELECT id INTO v_user_id FROM profiles WHERE id = auth.uid() AND role = 'admin';\n  IF v_user_id IS NULL THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: admin only');\n  END IF;\n\n  -- Validate new status\n  IF NOT (p_new_status = ANY(v_allowed_statuses)) THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Invalid status: ' || p_new_status);\n  END IF;\n\n  -- Get current status\n  SELECT status INTO v_old_status FROM quote_requests WHERE id = p_quote_id;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Quote not found');\n  END IF;\n\n  -- Update quote status\n  UPDATE quote_requests\n    SET status     = p_new_status,\n        updated_at = now()\n  WHERE id = p_quote_id;\n\n  -- Log the status change\n  INSERT INTO quote_status_logs (quote_id, from_status, to_status, changed_by, note)\n  VALUES (p_quote_id, v_old_status, p_new_status, v_user_id, p_note);\n\n  RETURN jsonb_build_object(\n    'success',      true,\n    'quote_id',     p_quote_id,\n    'from_status',  v_old_status,\n    'to_status',    p_new_status\n  );\nEND;\n$$","-- 6. Grant execute to authenticated users (will be checked inside function)\nGRANT EXECUTE ON FUNCTION update_quote_status(uuid, text, text) TO authenticated","-- 7. Helper: get quote status logs for a specific quote\nCREATE OR REPLACE FUNCTION get_quote_status_logs(p_quote_id uuid)\nRETURNS TABLE(\n  id          uuid,\n  quote_id    uuid,\n  from_status text,\n  to_status   text,\n  changed_by_name text,\n  note        text,\n  created_at  timestamptz\n)\nLANGUAGE sql\nSECURITY DEFINER\nAS $$\n  SELECT\n    qsl.id,\n    qsl.quote_id,\n    qsl.from_status,\n    qsl.to_status,\n    COALESCE(p.full_name, p.email::text, 'Hệ thống') AS changed_by_name,\n    qsl.note,\n    qsl.created_at\n  FROM quote_status_logs qsl\n  LEFT JOIN profiles p ON p.id = qsl.changed_by\n  WHERE qsl.quote_id = p_quote_id\n  ORDER BY qsl.created_at ASC;\n$$","GRANT EXECUTE ON FUNCTION get_quote_status_logs(uuid) TO authenticated"}	quote_workflow
